INSERT INTO investors (uuid, name, website, linkedin, dealroom_url, tagline, hq_city, hq_country, investor_types_json, deal_size_min, deal_size_max, investments_count, last_investment_date, currency, raw_json, fetched_at) VALUES ('b33be174-c396-4a07-8448-a3d4ab5fba92', 'Atomico', 'http://www.atomico.com', 'https://www.linkedin.com/company/atomico/', 'https://app.dealroom.co/investors/atomico', 'European venture capital firm backing ambitious tech founders from seed to growth stage', 'London', 'United Kingdom', '["venture capital"]', 1, 56818159, 292, '2026-10', 'GBP', '{"uuid":"b33be174-c396-4a07-8448-a3d4ab5fba92","type":"organization","domain":"atomico.com","name":"Atomico","tagline":"European venture capital firm backing ambitious tech founders from seed to growth stage","about":"Atomico is a European venture capital firm founded in 2006 by Niklas Zennström, the co-founder of Skype. Headquartered in London, with offices in Paris, Berlin, Stockholm and Luxembourg, it invests in ambitious technology companies across Europe from seed and Series A through to growth stage, and supports founders with an operational team covering talent, go-to-market, marketing and policy.\n\nIn September 2024 Atomico closed $1.24B across two funds: Atomico Venture VI ($485M) for early-stage deals and Atomico Growth VI ($754M) for growth rounds. Earlier funds include Atomico V ($820M, 2020) and Atomico IV ($765M, 2017).\n\nIts portfolio has included Klarna, Supercell, Graphcore, Lilium, Wolt, DeepL, Factorial, Neko Health, Raycast and The Exploration Company. Atomico also publishes the annual State of European Tech report.","image":"storage.googleapis.com/dealroom-images-production/2026/04/30/48ba998182e35420447d411a3f529c1c.png","dealroom_url":"https://app.dealroom.co/investors/atomico","links":{"website":"http://www.atomico.com","linkedin":"https://www.linkedin.com/company/atomico/","twitter":"https://x.com/atomico","instagram":null,"angellist":"https://angel.co/atomico","crunchbase":