INSERT INTO investors (uuid, name, website, linkedin, dealroom_url, tagline, hq_city, hq_country, investor_types_json, deal_size_min, deal_size_max, investments_count, last_investment_date, currency, raw_json, fetched_at) VALUES ('311bf922-e16f-4397-9259-89c2f4ed3107', 'Balderton Capital', 'https://www.balderton.com/', 'https://www.linkedin.com/company/balderton/', 'https://app.dealroom.co/investors/balderton_capital', 'Venture firm with a multi-stage approach and over twenty years of expertise in aiding European founders from the initial seed stage through to IPO', 'London', 'United Kingdom', '["venture capital"]', 1, 15151509, 580, '2026-10', 'GBP', '{"uuid":"311bf922-e16f-4397-9259-89c2f4ed3107","type":"organization","domain":"balderton.com","name":"Balderton Capital","tagline":"Venture firm with a multi-stage approach and over twenty years of expertise in aiding European founders from the initial seed stage through to IPO","about":"Balderton is Europe''s leading venture firm focused exclusively on backing European-founded tech companies. In the 26 years since its founding (as Benchmark Capital Europe, in 2000), Balderton has worked with hundreds of European founders and has raised more than $5.7bn across 12 funds. It takes a multi-stage approach, backing founders from seed through to IPO, most recently with the $615m Early Stage Fund IX and the $685m Growth Fund II announced in August 2024. Beyond capital, Balderton supports portfolio founders and teams through its talent, legal, finance and founder-wellbeing programmes, and through a bench of Executives in Residence.","image":"storage.googleapis.com/dealroom-images-production/2024/02/16/3b67841b3ad758aba42140c782b2d474.jpeg","dealroom_url":"https://app.dealroom.co/investors/balderton_capital","links":{"website":"https://www.balderton.com/","linkedin":"https://www.linkedin.com/company/balderton/","twitter":"https://twitter.com/balderton","instagram":null,"angellist":"https://angel.co/balderton-capital","crunchba