INSERT INTO investors (uuid, name, website, linkedin, dealroom_url, tagline, hq_city, hq_country, investor_types_json, deal_size_min, deal_size_max, investments_count, last_investment_date, currency, raw_json, fetched_at) VALUES ('d8795151-5792-40da-8cd9-8ede02bc58de', 'Index Ventures', 'http://www.indexventures.com', 'https://www.linkedin.com/company/index-ventures/', 'https://app.dealroom.co/investors/index_ventures', 'Elite global VC based in London, New York, San Francisco and Geneva, helping entrepreneurs turn bold ideas into transformative international businesses', 'London', 'United Kingdom', '["venture capital"]', 37879, 56818159, 1296, '2026-10', 'GBP', '{"uuid":"d8795151-5792-40da-8cd9-8ede02bc58de","type":"organization","domain":"indexventures.com","name":"Index Ventures","tagline":"Elite global VC based in London, New York, San Francisco and Geneva, helping entrepreneurs turn bold ideas into transformative international businesses","about":"Index Ventures is a venture capital firm based in London, San Francisco, New York and Geneva, helping entrepreneurs turn bold ideas into transformative international businesses. Since 1996, we''ve partnered with exceptional entrepreneurs in Europe, the U.S. and Israel, who are using technology to reshape the world around us. The companies they''ve started include Adyen, Deliveroo, Dropbox, Farfetch, King, Slack and Supercell. Now that technology is part of everyone''s life and reconfiguring the traditional economy, sector by sector, we are no longer just \"tech\" investors. Indeed, we are convinced that every aspect of human life and economic activity can be transformed and improved by technology and entrepreneurial passion -- and that we are just at the start of this era. Index covers every investment stage, from earliest seed through to explosive growth. We believe that opportunity is a mindset and we look for people who spot something others haven''t seen; something that they foresee can change the world and are committed to realising. More than anything, we are passionate about building lifelong relationships with the entrepreneurs we work with, which is why they are our best reference.","image":"storage.googleapis.com/dealroom-images-production/2026/10/26/5444215a7b3acd291e948b3a4fdafbf8.png","dealroom_url":"https://app.dealroom.co/investors/index_ventures","links":{"website":"http://www.indexventures.com","linkedin":"https://www.linkedin.com/company/index-ventures/","twitter":"https://x.com/indexventures","instagram":null,"angellist":"https://angel.co/index-seed","crunchbase":"https://www.crunchbase.com/organization/index-ventures"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.509804,"lon":-0.1407452},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.509804,"lon":-0.1407452},{"role":"office","city":{"id":1062031,"name":"Geneva"},"state":{"id":1047772,"name":"Canton of Geneva"},"country":{"id":183,"name":"Switzerland"},"continent":{"id":34,"name":"Europe"},"lat":46.201065,"lon":6.159802},{"role":"office","city":{"id":433111,"name":"New York City"},"state":{"id":432782,"name":"New York"},"country":{"id":233,"name":"United States"},"continent":{"id":84,"name":"North America"},"lat":40.712727,"lon":-74.00601},{"role":"office","city":{"id":241,"name":"San Francisco"},"state":{"id":111262,"name":"California"},"country":{"id":233,"name":"United States"},"continent":{"id":84,"name":"North America"},"lat":37.77967,"lon":-122.39127}],"roles":["investor","limited_partner","fund_manager"],"taxonomy":[{"id":35206,"name":"personalization","type":"techstack_category"},{"id":359001,"name":"Biotechnology","type":"sector"},{"id":325901,"name":"Social Media","type":"sector"},{"id":306501,"name":"Music","type":"se