INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('3776ab93-03cb-407a-b126-885fefa75499', 'Appear Here', 'appearhere.co.uk', 'http://www.appearhere.co.uk', 'https://www.linkedin.com/company/appearhere/', 'https://app.dealroom.co/companies/appear_here', 'List, discover and book short-term retail space around the UK', 'London', 'United Kingdom', 2013, 33, 26.923077, 26818171, 5, 840907, 2022, 'operational', '[{"uuid":"0f12d767-b2b1-47fc-a206-84ed27d95314","name":"Ross Bailey"}]', '{"uuid":"3776ab93-03cb-407a-b126-885fefa75499","type":"organization","domain":"appearhere.co.uk","name":"Appear Here","tagline":"List, discover and book short-term retail space around the UK","about":"Appear Here operates as an online marketplace for short-term retail space, often described as the ''Airbnb for retail''. The company was founded in 2012 by Ross Bailey, whose entrepreneurial drive was sparked by observing his parents run their hair salon. The specific idea for the company originated after Bailey launched a pop-up shop called Rock and Rule for the Queen''s Diamond Jubilee. He discovered a significant demand from others who also wanted to rent retail space flexibly, prompting him to use the profits from his pop-up to establish Appear Here.\n\nThe platform addresses the traditionally slow and complex process of securing commercial real estate, which can take 3-6 months. Appear Here streamlines this, reducing the booking time to as little as 3-6 days. The business model is designed to create a transparent marketplace that connects landlords with brands seeking to create pop-up shops, launch events, or test new markets. Revenue is generated through a multi-faceted approach; the company charges landlords a service fee for listing and marketing their spaces and also takes a booking fee or commission from tenants upon successful rental. This model disrupts the traditional brokerage system, where agents are often disincentivized to work on short-term deals.\n\nThe company serves a wide range of clients, from major international brands like Apple, Chanel, and Nike to thousands of independent designers and creative entrepreneurs. Its marketplace lists thousands of exclusive spaces in major global cities, including London, Paris, and New York. These spaces range from high-street shops and shopping mall units to unique venues like underground stations. A notable partnership with Transport for London involved transforming Old Street Station into a dedicated pop-up retail destination. To date, the company has raised over $49 million from investors such as Balderton Capital, Octopus Ventures, and MMC Ventures, facilitating its international expansion and the launch of over 10,000 stores.\n\nKeywords: retail marketplace, pop-up shops, short-term leasing, commercial real estate, proptech, flexible retail, brand activation, online booking, sharing economy, retail-as-a-service","image":"storage.googleapis.com/dealroom-images-production/2026/10/27/eca7a290f870f1f50511f160f7d17b7a.png","dealroom_url":"https://app.dealroom.co/companies/appear_here","links":{"website":"http://www.appearhere.co.uk","linkedin":"https://www.linkedin.com/company/appearhere/","twitter":"https://twitter.com/appearhere","instagram":null,"angellist":"https://angel.co/appear-here","crunchbase":"http://www.crunchbase.com/organization/appear-here"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":