INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('4f1c6e46-3831-42f9-b1bf-be3b4b4642e0', 'Bloom & Wild', 'bloomandwild.com', 'http://www.bloomandwild.com', 'https://www.linkedin.com/company/bloom-&-wild/', 'https://app.dealroom.co/companies/bloom_wild', 'An online flower delivery platform developing a modern approach for sending flowers to loved ones', 'London', 'United Kingdom', 2014, 299, 7.9422383, 126250000, 5, 116569306, 2025, 'operational', '[{"uuid":"a1693d8b-ac0f-43f7-a781-0abb95bdfaa2","name":"Ben Stanway"},{"uuid":"dfb1c339-e48e-4a8a-8bb7-f6c0398be840","name":"Aron Gelbard"}]', '{"uuid":"4f1c6e46-3831-42f9-b1bf-be3b4b4642e0","type":"organization","domain":"bloomandwild.com","name":"Bloom & Wild","tagline":"An online flower delivery platform developing a modern approach for sending flowers to loved ones","about":"Bloom & Wild is a UK-based online florist startup that operates in the e-commerce sector. The company specializes in delivering fresh, designer-quality flowers in bespoke packaging that fits through a standard letterbox. This innovative approach to flower delivery eliminates the need for recipients to be at home to receive their flowers, providing a unique selling point in the competitive online florist market.\n\nBloom & Wild serves a broad range of clients, from individuals looking to send a thoughtful gift, to businesses seeking corporate flower services. The company operates primarily in the UK, but also offers delivery to several European countries.\n\nThe business model of Bloom & Wild is based on both one-off purchases and subscription services. Customers can order individual bouquets for special occasions or opt for a regular flower delivery through a subscription model. This recurring revenue stream provides a stable income for the company and encourages customer loyalty.\n\nBloom & Wild generates revenue through the sale of its flower arrangements and subscriptions. The company also offers add-on products such as vases and chocolates, providing additional income streams. \n\nBloom & Wild has leveraged technology to enhance its business operations. The company uses data analytics to understand customer preferences and optimize its product offerings. It also utilizes various digital marketing strategies to reach a wider audience and drive sales.\n\nKeywords: Online Florist, E-commerce, Letterbox Flowers, Subscription Model, One-off Purchases, Corporate Flower Services, International Delivery, Add-on Products, Data Analytics, Digital Marketing.","image":"storage.googleapis.com/dealroom-images-production/2025/08/23/82cea40cf1bc1bbab5b4e80f73bed262.png","dealroom_url":"https://app.dealroom.co/companies/bloom_wild","links":{"website":"http://www.bloomandwild.com","linkedin":"https://www.linkedin.com/company/bloom-&-wild/","twitter":"https://twitter.com/bloomandwild","instagram":"bloomandwild","angellist":"https://angel.co/bloom-wild","crunchbase":"https://www.crunchbase.com/organization/bloom-wild"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.486244,"lon":-0.1188947},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.486244,"lon":-0.1188947},{"role":"office","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingd