eed for recipients to be at home to receive their flowers, providing a unique selling point in the competitive online florist market.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('d8f8a059-3a3b-48ce-b72f-c82c22b02990', 'Carwow', 'carwow.co.uk', 'http://www.carwow.co.uk/', 'https://www.linkedin.com/company/carwow/', 'https://app.dealroom.co/companies/carwow', 'Carwow is an online car marketplace that connects customers, automotive brands and car dealers', 'London', 'United Kingdom', 2013, 609, 5, 174081766, 10, 104200000, 2025, 'operational', '[{"uuid":"7016f45c-0264-42f2-8ec0-2c58d067b9ae","name":"David Santoro"},{"uuid":"6c52ef7b-9673-42d0-abc0-08e6b27fc522","name":"Alexandra Margolis"},{"uuid":"b0a577b2-dbf1-4398-9639-d76912144902","name":"James Hind"}]', '{"uuid":"d8f8a059-3a3b-48ce-b72f-c82c22b02990","type":"organization","domain":"carwow.co.uk","name":"Carwow","tagline":"Carwow is an online car marketplace that connects customers, automotive brands and car dealers","about":"Carwow is a UK-based online platform that simplifies the process of buying and selling cars. It operates in the automotive retail market, serving a broad range of clients, from individual car owners to car dealerships. The platform''s primary function is to connect buyers and sellers, eliminating the need for haggling and providing a transparent, hassle-free experience. \n\nCarwow''s business model is centered around facilitating transactions between car buyers and sellers. It allows sellers to list their cars for sale, and buyers can browse these listings, compare prices, and make purchases. The platform also offers a bidding feature, where over 4,000 dealers across the UK can bid on listed cars. This competitive environment ensures that sellers get the best possible price for their vehicles. \n\nIn addition to its marketplace function, Carwow also provides a wealth of information for car enthusiasts and potential buyers. It hosts a popular YouTube channel with over 70 million views per month, offering in-depth car reviews and the latest car news. The platform is also home to hundreds of independent reviews, providing unbiased insights into various car models. \n\nCarwow generates revenue through fees charged to dealers for each successful transaction. It also monetizes its YouTube channel through ad revenue. The company''s strong reputation, as evidenced by its ''Excellent'' rating on Trustpilot, indicates a high level of customer satisfaction and trust in its services.\n\nKeywords: Online Car Marketplace, Car Buying, Car Selling, Car Dealerships, Bidding Platform, Car Reviews, YouTube Channel, Trustpilot, Automotive Retail Market, Transaction Fees.","image":"storage.googleapis.com/dealroom-images-production/2026/10/28/d725d40cae1e8f5273eb4e3ad5add1b7.png","dealroom_url":"https://app.dealroom.co/companies/carwow","links":{"website":"http://www.carwow.co.uk/","linkedin":"https://www.linkedin.com/company/carwow/","twitter":"https://twitter.com/carwowuk","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/carwow"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.498257,"lon":-0.142408},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.498257,"lon":-0.142408},{"role":"office","city":{"id":221,"name":"Munich"},"state":{"id":130742,"name":"Bavaria"},"country":{"id":133,"name":"Germany"},"continent":{"id":34,"name":"Eur