signal_rating","items":[{"raw_title":null,"titles":["CTO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2013","end_date":null,"person":{"name":"David Santoro","type":"person","uuid":"7016f45c-0264-42f2-8ec0-2c58d067b9ae","image":"storage.googleapis.com/dealroom-images-production/2025/04/17/4cbcfbf28ab11514ef01d202cc768d8e.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/david_santoro_2","classifications":["super_founder"]}},{"raw_title":"Designer","titles":["Brand","Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2013","end_date":null,"person":{"name":"Alexandra Margolis","type":"person","uuid":"6c52ef7b-9673-42d0-abc0-08e6b27fc522","image":"storage.googleapis.com/dealroom-images-production/2025/05/23/0d05d30be3e7c4d7acc95a832ec255ac.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/alexandra_margolis","classifications":["super_founder"]}},{"raw_title":"Founder,CEO","titles":["CEO","Director","Founder","Non Executive Director"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2013","end_date":null,"person":{"name":"James Hind","type":"person","uuid":"b0a577b2-dbf1-4398-9639-d76912144902","image":"storage.googleapis.com/dealroom-images-production/2025/05/23/538b711e629a3e9c0c6ed5685aebef70.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/james_hind","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":104200000,"year":2025},"traffic":{"monthly_visits":6900000,"growth_3m":3},"available":["founders","revenue","traffic","portfolio","exits"]}', '2026-11-05T15:41:48.292Z', 'Carwow is a UK-based online platform that simplifies the process of buying and selling cars. It operates in the automotive retail market, serving a broad range of clients, from individual car owners to car dealerships. The platform''s primary function is to connect buyers and sellers, eliminating the need for haggling and providing a transparent, hassle-free experience. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('6f985058-99f1-4118-9831-01a44a978c3b', 'Cleo', 'meetcleo.com', 'http://meetcleo.com', 'https://www.linkedin.com/company/cleo-ai/', 'https://app.dealroom.co/companies/cleo', 'AI financial assistant for budgeting and saving', 'London', 'United Kingdom', 2016, 733, 31.362007, 104246625, 6, 303030182, 2026, 'operational', '[{"uuid":"8a9ee26e-0b84-4e66-bc26-30cc9c418b77","name":"Barnaby Hussey-Yeo"}]', '{"uuid":"6f985058-99f1-4118-9831-01a44a978c3b","type":"organization","domain":"meetcleo.com","name":"Cleo","tagline":"AI financial assistant for budgeting and saving","about":"Cleo is an AI-powered financial assistant designed to help users, particularly Gen Z and millennials, manage their money through a conversational interface. The company was founded in 2016 by Barney Hussey-Yeo, a data scientist with a master''s degree in Machine Learning. Hussey-Yeo was motivated by his own struggles with money management and his experience at payday loan company Wonga, where he observed that customers were offered credit with little guidance on financial literacy. He began by creating scripts that would analyze his own banking and send him text alerts, an idea that evolved into Cleo. \n\nThe company launched through the Entrepreneurs First accelerator program, initially as a chatbot on Facebook Messenger in the UK. After seeing rapid user adoption, Cleo entered the U.S. market in 2018 and shifted its focus entirely to this region. The platform operates on a freemium business model. The free version offers basic features like spending analysis, budget tracking, and bill reminders through its AI chatbot. Cleo''s AI communicates with a distinct, often humorous and sassy personality, offering features like \"Roast Mode\" to critique spending habits and \"Hype Mode\" to praise financial progress. \n\nCleo generates revenue through tiered subscription plans that unlock advanced features. These premium tiers, such as Cleo Plus and Cleo Builder, provide services including interest-free cash advances up to $250, credit-building cards issued by WebBank, and enhanced financial insights. The Credit Builder Card is a secured card designed to help users establish or improve their credit scores. The company also earns interchange fees from transactions made with its card and fees from its cash advance service. Banking services are provided through a partnership with Thread Bank. \n\nCleo has raised a total of approximately $175 million in funding over several rounds, with a Series C round of $80 million in 2022 led by Sofina. Other key investors include Balderton Capital, EQT Ventures, and LocalGlobe. The company was last valued at $500 million in 2022 and has demonstrated significant revenue growth, nearing profitability. Headquartered in London, Cleo has grown to a team of over 300 employees and has attracted millions of users, primarily in the United States. \n\nKeywords: AI financial assistant, personal finance, budgeting app, money management, chatbot, spending tracker, credit builder, cash advance, savings goals, fintech, Gen Z finance, financial health, AI money coach, expense tracking, overdraft protection, financial education, subscription model, transaction analysis, automated savings, credit score improvement","image":"storage.googleapis.com/dealroom-images-production/2025/09/21/fd0e9d129a1d7d0cd153321e9eacf8a4.png","dealroom_url":"https://app.dealroom.co/companies/cleo","links":{"website":"http://meetcleo.com","linkedin":"https://www.linkedin.com/company/cleo-ai/","twitter":"https://twitter.com/meetcleo","instagram":"meetcleo","angellist":"https://angel.co/cleo-ai","crunchbase":"http://www.crunchbase.com/organization/cleo-ai"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.52003,"lon":-0.0861771},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.52003,"lon":-0.0861771},{"role":"office","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.5258,"lon":-0.0929653},{"role":"office","city":{"id":433111,"name":"New York City"},"state":{"id":432782,"name":"New York"},"country":{"id":233,"name":"United States"},"continent":{"id":84,"name":"North America"},"lat":40.74478,"lon":-73.99388}],"roles":[],"taxonomy":[{"id":35206,"name":"personalization","type":"techstack_category"},{"id":10006,"name":"data management","type":"techstack_category"},{"id":45606,"name":"social media marketing software","type":"techstack_category"},{"id":12006,"name":"database","type":"techstack_category"},{"id":2295201,"name":"uk is8 financial services","type":"sector"},{"id":51406,"name":"software as a service","type":"techstack_category"},{"id":30406,"name":"online community software","type":"techstack_category"},{"id":7506,"name":"corporate learning management systems","type":"techstack_category"},{"id":606,"name":"accounting","type":"techstack_category"},{"id":22906,"name":"human resource management system","type":"techstack_category"},{"id":54706,"name":"ticket booking","type":"techstack_category"},{"id":22206,"name":"hris management","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":12806,"name":"e-com