ll,"investor":null,"funding":{"total":104246625,"total_vc":104246625,"rounds_count":6},"valuation":{"value":757575455,"year":2025,"month":9},"jobs":{"is_hiring":true,"open_count":50},"founders":{"total":1,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":"Founder and Chief Executive Officer","titles":["CEO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"Barnaby Hussey-Yeo","type":"person","uuid":"8a9ee26e-0b84-4e66-bc26-30cc9c418b77","image":"storage.googleapis.com/dealroom-images-production/2024/12/12/e91c3629173a33319a58eed87a0d7f04.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/barnaby_hussey_yeo","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":303030182,"year":2026},"traffic":{"monthly_visits":590000,"growth_3m":-41},"available":["founders","revenue","traffic"]}', '2026-11-05T15:42:01.499Z', 'Cleo is an AI-powered financial assistant designed to help users, particularly Gen Z and millennials, manage their money through a conversational interface. The company was founded in 2016 by Barney Hussey-Yeo, a data scientist with a master''s degree in Machine Learning. Hussey-Yeo was motivated by his own struggles with money management and his experience at payday loan company Wonga, where he observed that customers were offered credit with little guidance on financial literacy. He began by creating scripts that would analyze his own banking and send him text alerts, an idea that evolved into Cleo. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('76300f5d-5264-40b1-8691-51a1a327fe35', 'ComplyAdvantage', 'complyadvantage.com', 'https://complyadvantage.com', 'https://www.linkedin.com/company/complyadvantage', 'https://app.dealroom.co/companies/complyadvantage', 'ComplyAdvantage is the financial industry’s leading source of AI-driven financial crime risk data and detection technology', 'London', 'United Kingdom', 2014, 510, 7.82241, 81969664, 4, 47428878, 2025, 'operational', '[{"uuid":"a66e360c-66b6-4c5d-93b0-ac3b66e3262a","name":"Charles Delingpole"}]', '{"uuid":"76300f5d-5264-40b1-8691-51a1a327fe35","type":"organization","domain":"complyadvantage.com","name":"ComplyAdvantage","tagline":"ComplyAdvantage is the financial industry’s leading source of AI-driven financial crime risk data and detection technology","about":"ComplyAdvantage specializes in providing advanced anti-money laundering (AML) data and technology solutions to financial institutions and digital financial service providers. The company operates in the compliance and regulatory technology market, offering tools that automate labor-intensive processes and significantly reduce false positive rates in compliance checks. ComplyAdvantage''s core services include customer screening and monitoring, adverse information and media screening, transaction screening, and transaction monitoring. These services are delivered through API-enabled, cloud-native solutions that easily integrate with existing workflows. The business model is subscription-based, where clients pay for access to the platform and its various features. ComplyAdvantage generates revenue by offering tiered pricing plans based on the volume of transactions and the level of service required. The company serves a diverse client base, including traditional financial institutions and emerging digital financial service providers, helping them meet regulatory requirements and combat financial crime efficiently. \n\nKeywords: AML, KYC, compliance, financial crime, risk scoring, API, cloud-native, transaction monitoring, customer screening, regulatory technology.","image":"storage.googleapis.com/dealroom-images-production/2026/10/27/54a346821149b2bded8e7000f1561c6a.png","dealroom_url":"https://app.dealroom.co/companies/complyadvantage","links":{"website":"https://complyadvantage.com","linkedin":"https://www.linkedin.com/company/complyadvantage","twitter":"https://twitter.com/complyadvantage","instagram":"complyadvantage","angellist":"https://angel.co/comply-advantage","crunchbase":"http://www.crunchbase.com/organization/comply-advantage"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.517227,"lon":-0.1096505},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.517227,"lon":-0.1096505},{"role":"office","city":{"id":1097151,"name":"Cluj-Napoca"},"state":{"id":1097142,"name":"Cluj"},"country":{"id":1523,"name":"Romania"},"continent":{"id":34,"name":"Europe"},"lat":46.77781,"lon":23.57139},{"role":"office","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.507446,"lon":-0.1277653},{"role":"office","city":{"id":433111,"name":"New York City"},"state":{"id":432782,"name":"