e,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2012","end_date":null,"person":{"name":"Mark Faulkner","type":"person","uuid":"9f57aa49-f1fa-42bb-909f-2be52b021cae","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/ecb4d69a10bf805dffd7f7e9d28b1337.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/mark_faulkner_1","classifications":["super_founder"]}},{"raw_title":null,"titles":["Executive Chairman","Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2012","end_date":null,"person":{"name":"Donal Smith","type":"person","uuid":"9aca9590-cd5e-4e05-99db-c170eec31077","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/30386bbd681ee72810510b40d9ad70bd.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/donal_smith","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":4833331,"year":2023},"traffic":{"monthly_visits":8100,"growth_3m":-46},"available":["founders","revenue","traffic"]}', '2026-11-05T15:41:48.292Z', 'Credit Benchmark aggregates and anonymizes internal credit risk assessments from over 40 leading global financial institutions to provide consensus ratings and analytics. These insights offer an independent perspective on credit risk, which is crucial for risk and investment professionals at banks, insurance companies, asset managers, and other financial firms. The company operates in the financial services market, focusing on credit risk data and analytics. By collecting and publishing these aggregated views, Credit Benchmark helps its clients monitor and manage credit risk within their portfolios, benchmark against industry standards, and gain insights into unrated entities. The business model revolves around providing subscription-based access to its data and analytics platform, generating revenue from financial institutions that rely on this information for risk management and investment decisions.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('a52e47df-37b4-4b66-8bcd-841b8f96dcda', 'Crowdcube', 'crowdcube.com', 'http://www.crowdcube.com', 'https://www.linkedin.com/company/crowdcube-limited/', 'https://app.dealroom.co/companies/crowdcube', 'An online crowdfunding service that enables individuals to invest or loan small amounts in small companies in return for equity or an annual return', 'London', 'United Kingdom', 2010, 123, 6.034483, 37739999, 8, 9761263, 2024, 'operational', '[{"uuid":"533a8815-7fe3-40e5-9a8d-133ea0713e11","name":"Darren Westlake"}]', '{"uuid":"a52e47df-37b4-4b66-8bcd-841b8f96dcda","type":"organization","domain":"crowdcube.com","name":"Crowdcube","tagline":"An online crowdfunding service that enables individuals to invest or loan small amounts in small companies in return for equity or an annual return","about":"Crowdcube is a leading equity crowdfunding platform for entrepreneurs of start-ups and growing businesses to connect with potential investors. Dedicated to helping UK-based entrepreneurs raise finance to start or grow their business, Crowdcube gives investors real equity in the companies they fund. Crowdcube uses the web-based notion of ‘crowdfunding’ where a community of like minded people pool their money and knowledge together to back an idea, business or person.  Risk Warning: Investing in start-ups and early stage businesses involves risks, including illiquidity, lack of dividends, loss of investment and dilution, and it should be done only as part of a diversified port