,"start_date":"2015","end_date":null,"person":{"name":"Roberto Valdes","type":"person","uuid":"c3fbde37-07bf-493e-8316-8592f2de00bc","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/8e4b842361fe822f8fe1790625532995.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/roberto_valdes","classifications":["super_founder"]}},{"raw_title":null,"titles":["CEO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2015","end_date":null,"person":{"name":"Adrià Buzón Lausín","type":"person","uuid":"a2c34c0c-292d-4cbe-a217-3638518ff76c","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/28df5c229d097a22d15e244e7a95b583.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/adri_buz_n_laus_n","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":2799897,"year":2023},"traffic":{"monthly_visits":77000,"growth_3m":-23},"available":["founders","revenue","traffic","portfolio","exits"]}', '2026-11-05T15:42:06.285Z', 'Cuideo specializes in providing personalized home care services for the elderly, ensuring their comfort and quality of life through professional caregivers. The company operates in the home healthcare market, primarily serving elderly individuals and their families who seek reliable and compassionate care solutions. Cuideo''s business model revolves around matching qualified caregivers with clients based on their specific needs and preferences. The company generates revenue through service fees charged for the caregiving services provided. By leveraging a network of vetted caregivers, Cuideo ensures high standards of care and support for its clients.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('a73bc702-a09f-4301-8322-d49aeda6f4a7', 'Daye', 'yourdaye.com', 'https://yourdaye.com/', 'https://www.linkedin.com/company/yourdaye/', 'https://app.dealroom.co/companies/daye', 'Gynaecological health platform for at-home diagnostic testing', 'London', 'United Kingdom', 2017, 119, 16.666666, 16404023, 5, NULL, NULL, 'operational', '[{"uuid":"d6e81202-91e4-443e-a501-8f8e9acfcdd9","name":"Valentina Milanova"}]', '{"uuid":"a73bc702-a09f-4301-8322-d49aeda6f4a7","type":"organization","domain":"yourdaye.com","name":"Daye","tagline":"Gynaecological health platform for at-home diagnostic testing","about":"Daye is a UK-based gynaecological health company developing products and services to address gaps in medical research and innovation for women''s health. The company was founded in 2017 by Valentina Milanova, who was motivated by her personal struggles with menstrual pain and the lack of effective solutions. Milanova, who previously worked in venture capital at Founders Factory and Techstars, initially envisioned a research-focused NGO before opting for a startup structure to raise funds for clinical trials. \n\nThe company''s first product, launched in 2020, was the world''s first CBD-infused tampon, designed to provide localized relief from menstrual cramps. Building on this, Daye introduced a tampon-based at-home screening kit. This platform enables users to test for disruptions in the vaginal microbiome, which can indicate susceptibility to infections like bacterial vaginosis (BV) and yeast infections. The service has expanded to include screening for STIs such as chlamydia, gonorrhoea, and trichomonas, as well as HPV, using PCR technology for analysis in accredited labs. The business model operates on a direct-to-consumer basis, selling products like organic tampons, diagnostic kits, and supplements via its website, with options for monthly subscriptions. The company also provides personalized aftercare, including prescription treatments and consultations with healthcare specialists. \n\nDaye has raised approximately $18.6 million (£14 million) in funding through several rounds, including a Series A round of £10 million ($11.5 million) in October 2022. Key investors include Hambro Perks, MassMutual Ventures, Khosla Ventures, and Index Ventures. The company is preparing for expansion into the U.S. market and aims to develop a comprehensive digital health platform covering conditions like PCOS and endometriosis. \n\nKeywords: gynaecological health, femtech, at-home diagnostics, vaginal microbiome screening, STI testing, menstrual health, CBD tampons, period care, Valentina Milanova, women''s health research, digital health platform, telehealth, direct-to-consumer, venture capital, medical devices, HPV screening, personalized medicine, femcare, pelvic pain, subscription service","image":"storage.googleapis.com/dealroom-images-production/2026/02/05/11e4a3c73874727da1d438458c6e9d45.png","dealroom_url":"https://app.dealroom.co/companies/daye","links":{"website":"https://yourdaye.com/","linkedin":"https://www.linkedin.com/company/yourdaye/","twitter":"https://twitter.com/meetdaye","instagram":"yourdaye","angellist":null,"crunchbase":"https://www.crunchbase.com/organization/daye"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.494064,"lon":-0.0631783},{"role":"founding","city":{"id":628061,"