INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('89e3d05d-d4d9-4611-a73d-86cba4e98635', 'Drivetribe', 'drivetribe.com', 'http://drivetribe.com', 'https://www.linkedin.com/company/drivetribe/', 'https://app.dealroom.co/companies/drivetribe', 'Social network for motorheads', 'London', 'United Kingdom', 2016, 23, 4.5454545, 9090905, 3, 2469695, 2023, 'operational', '[{"uuid":"644677ec-1c6e-4f76-8f04-cc8ae05e4faf","name":"Richard Hammond"},{"uuid":"bf78ab3b-4d37-4009-b497-46913e66ee0b","name":"Jeremy Clarkson"},{"uuid":"283b6291-c007-46e0-87a9-5dadad6fa639","name":"James May"},{"uuid":"9adaeb18-7d2a-4f73-bf4f-2bb4d591d7ca","name":"Andy Wilman"}]', '{"uuid":"89e3d05d-d4d9-4611-a73d-86cba4e98635","type":"organization","domain":"drivetribe.com","name":"Drivetribe","tagline":"Social network for motorheads","about":"Drivetribe emerged in late 2016 from the combined vision of former \"Top Gear\" personalities Jeremy Clarkson, Richard Hammond, and James May, alongside serial entrepreneur Ernesto Schmitt and producer Andy Wilman. The venture was conceived as a digital hub for automotive enthusiasts, a specialized social network where users could form and join communities, or \"Tribes,\" based on their specific motoring interests. This journey began after the founders'' departure from the BBC, creating a parallel digital venture to their new show, \"The Grand Tour,\" on Amazon Prime. \n\n Financially, the platform launched with substantial backing, securing a total of $12 million from notable investors, including Breyer Capital, Atomico, and 21st Century Fox. The business model initially focused on leveraging the massive global automotive advertising market through native advertising and social commerce. It later evolved to a four-pronged approach encompassing content creation, distribution, data insights, and client engagement with major brands like Audi and Renault. The platform''s tech stack was built to extract real-time data analytics from user interactions, providing valuable insights to the automotive industry. \n\n Despite rapid initial user growth, reaching 140 million monthly platform users by 2021, Drivetribe faced financial headwinds. The company reported significant losses in its early years and found sustained profitability challenging. In January 2022, facing industry-wide marketing budget cuts and the global chip shortage, the company announced the shutdown of its website and app. The brand, however, did not disappear. Richard Hammond acquired the Drivetribe brand, transitioning the business to focus on its successful social media channels, particularly YouTube. This strategic pivot was followed by the acquisition of video production agency Centric Creative in October 2023, repositioning Drivetribe as a full-service automotive content production and distribution house, offering end-to-end marketing solutions for automotive brands. \n\n Keywords: automotive community, social media, content platform, digital media, Jeremy Clarkson, Richard Hammond, James May, video production, automotive marketing, online publishing","image":"storage.googleapis.com/dealroom-images-production/2026/10/27/bfacfcb34e8e7096eb15371939f147c7.png","dealroom_url":"https://app.dealroom.co/companies/drivetribe","links":{"website":"http://drivetribe.com","linkedin":"https://www.linkedin.com/company/drivetribe/","twitter":"https://twitter.com/drivetribe","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/drivetribe"},"locations":[{"role":"hq","city":{"id":628061,