-production/2019/06/20/354a044e1bb466e64929db2cb57d6c59.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/richard_hammond","classifications":["serial_founder","strong_founder"]}},{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"Jeremy Clarkson","type":"person","uuid":"bf78ab3b-4d37-4009-b497-46913e66ee0b","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/3c24e7cc052ef785d2edaa2f4a940d34.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/jeremy_clarkson","classifications":["strong_founder"]}},{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"James May","type":"person","uuid":"283b6291-c007-46e0-87a9-5dadad6fa639","image":"storage.googleapis.com/dealroom-images-production/2019/06/24/a38fb250082ee1bbe95f223d7f9486e9.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/james_may","classifications":["serial_founder","strong_founder"]}},{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"Andy Wilman","type":"person","uuid":"9adaeb18-7d2a-4f73-bf4f-2bb4d591d7ca","image":"storage.googleapis.com/dealroom-images-production/2019/06/24/dde944b3ec65ae2156bf2b99d87d0461.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/andy_wilman","classifications":["strong_founder"]}}]},"patents":null,"revenue":{"value":2469695,"year":2023},"traffic":{"monthly_visits":18000,"growth_3m":-22},"available":["founders","revenue","traffic","portfolio","exits"]}', '2026-11-05T15:42:01.499Z', 'Drivetribe emerged in late 2016 from the combined vision of former "Top Gear" personalities Jeremy Clarkson, Richard Hammond, and James May, alongside serial entrepreneur Ernesto Schmitt and producer Andy Wilman. The venture was conceived as a digital hub for automotive enthusiasts, a specialized social network where users could form and join communities, or "Tribes," based on their specific motoring interests. This journey began after the founders'' departure from the BBC, creating a parallel digital venture to their new show, "The Grand Tour," on Amazon Prime. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('ab81e00d-7326-478f-92d7-87307b288026', 'Durcal', 'durcal.com', 'https://durcal.com/es/', 'https://www.linkedin.com/company/durcal/', 'https://app.dealroom.co/companies/alpify', 'The app to take care of loved ones and ensure everyone''s safety', 'Barcelona', 'Spain', 2012, 38, 8.571428, 13383707, 9, 2803029, 2023, 'operational', '[{"uuid":"1ad2e469-1f42-470a-affd-38d61b2e7bde","name":"Guillem Viladomat"}]', '{"uuid":"ab81e00d-7326-478f-92d7-87307b288026","type":"organization","domain":"durcal.com","name":"Durcal","tagline":"The app to take care of loved ones and ensure everyone''s safety","about":"Durcal is a technology company operating in the eldercare and family safety market, providing a suite of services centered around a GPS tracking application and a complementary smartwatch. Founded in 2014 by Guillem Viladomat and headquartered in Barcelona, Spain, the company aims to enhance the safety and well-being of seniors, enabling them to live more independently while offering peace of mind to their families. \n\nThe core of Durcal''s offering is its mobile application, which serves as a platform for families to monitor the health and location of their elderly relatives. A key hardware component is the Durcal smartwatch, designed specifically for seniors. This device integrates several critical features, including real-time GPS location tracking, automatic fall detection via an accelerometer, and a prominent help button that connects the user directly to an emergency call center. This call center service ensures that professional help can be dispatched immediately, even if family members are unreachable. The watch can also monitor vital signs like heart rate and oxygen saturation, providing a comprehensive overview of the user''s health to their connected caregivers through the app. A significant advantage of the system is that it does not require the user to have an internet connection at their home for these core functionalities to work. \n\nDurcal''s business model is twofold. It generates revenue from the sale of the smartwatch and through subscription fees for the monitoring services and connectivity. The company targets families and caregivers who are looking for reliable, non-intrusive ways to ensure the safety of their aging loved ones. By integrating hardware, software, and a 24/7 response service, Durcal provides an end-to-end solution. The firm has successfully raised capital to fuel its growth, securing €8 million in a 2022 funding round with participation from notable investors like Telefónica, Atresmedia, Mangrove Capital Partners, and K Fund. Overall, the company has raised approximately $17.4 million across several funding rounds since its inception. \nKeywords: eldercare technology, senior safety, GPS tracking watch, fall detection, personal emergency response system, remote health monitoring, family safety app, senior care, vital signs monitoring, telecare services, independent living technology, caregiver support, medical alert device, gerontechnology, GPS for seniors, emergency call service, connected health, assistive technology, mobile personal emergency response, wearables for seniors","image":"storage.googleapis.com/dealroom-images-production/2026/10/26/26530ae9707d692869e27a0d8fe36623.png","dealroom_url":"https://app.dealroom.co/companies/alpify","links":{"website":"https://durcal.com/es/","linkedin":"https://www.linkedin.com/company/durcal/","twitter":"https://twitter.com/durcal_app","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/alpify"},"locations":[{"role":"hq","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":41.387157,"lon":2.1671717},{"role":"founding","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":41.387157,"lon":2.1671717}],"roles":[],"taxonomy":[{"id":114407,"name":"accelerator","type":"ownership"},{"id":2261501,"name":"elderly care","type":"sector"},{"id":35706,"name":"photo galleries","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":48906,"name":"web fonts","type":"techstack_category"},{"id":1198501,"name":"Web Development","type":"sector"},{"id":83608,"name":"SaaS","type":"business_model"},{"id":24006,"name":"javascript graphics","type":"techstack_category"},{"id":113707,"name":"Angel","type":"ownership"},{"id":51106,"name":"content management system","type":"techstack_category"},{"id":28906,"name":"other advertising software","type":"techstack_category"},{"id":31606,"name":"online video platforms","type":"techstack_category"},{"id":2288701,"name":"DT and LS","type":"sector"},{"id":25806,"name":"it infrastructure","type":"techstack_category"},{"id":49006,"name":"web frameworks","type":"techstack_category"},{"id":55106,"name":"web platform extensions","type":"techstack_category"},{"id":41806,"name":"tag management","type":"techstack_category"},{"id":50006,"name":"widgets","type":"techstack_category"},{"id":47606,"name":"web servers","type":"techstack_category"},{"id":39906,"name":"search engines","type":"techstack_category"},{"id":43706,"name":"software framework","type":"techstack_category"},{"id":2239001,"name":"Hard Tech","type":"sector"},{"id":35106,"name":"programming languages","type":"techstack_category"},{"id":209,"name":"Commission","type":"