date":null,"employees_count":38,"added_at":"2013-10-01T11:00:00.000Z","updated_at":"2026-11-05T01:02:01.846Z","subtype":"company","classifications":["startup","vc_backed","funded"],"employee_count_1y_growth":8.571428,"status":"operational","signal_rating":82.07,"unicorn_type":null,"became_unicorn_date":null,"became_thoroughbred_date":null,"exit_date":null,"investor":null,"funding":{"total":13383707,"total_vc":13383707,"rounds_count":9},"valuation":{"value":39999984,"year":2022,"month":5},"jobs":{"is_hiring":false,"open_count":0},"founders":{"total":1,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":"Founder","titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2012","end_date":null,"person":{"name":"Guillem Viladomat","type":"person","uuid":"1ad2e469-1f42-470a-affd-38d61b2e7bde","image":"storage.googleapis.com/dealroom-images-production/2026/09/27/f811a3a8fe02563abd5d37a60fa5717b.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/guillem_viladomat","classifications":["strong_founder"]}}]},"patents":null,"revenue":{"value":2803029,"year":2023},"traffic":{"monthly_visits":13000,"growth_3m":0},"available":["founders","revenue","traffic"]}', '2026-11-05T15:42:24.857Z', 'Durcal is a technology company operating in the eldercare and family safety market, providing a suite of services centered around a GPS tracking application and a complementary smartwatch. Founded in 2014 by Guillem Viladomat and headquartered in Barcelona, Spain, the company aims to enhance the safety and well-being of seniors, enabling them to live more independently while offering peace of mind to their families. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('c8fdecc2-91ad-488f-88d8-166e57b5b387', 'Electric Playbox', 'electricplaybox.com', 'https://electricplaybox.com/', 'https://www.linkedin.com/company/immersivegamebox/', 'https://app.dealroom.co/companies/electronic_theatre', 'Delivers immersive adventures in interactive digital rooms', 'London', 'United Kingdom', 2018, 129, 14.159292, 19833330, 3, NULL, NULL, 'operational', '[{"uuid":"f5e8fb57-6efc-434d-bb3c-6cb42ce919c7","name":"Will Dean"}]', '{"uuid":"c8fdecc2-91ad-488f-88d8-166e57b5b387","type":"organization","domain":"electricplaybox.com","name":"Electric Playbox","tagline":"Delivers immersive adventures in interactive digital rooms","about":"Immersive Gamebox, formerly known as Electric Playbox, is a social entertainment and gaming company founded in 2018 by Will Dean and David Spindler. Dean, who previously founded the Tough Mudder endurance events, and Spindler, who co-founded Tough Mudder Bootcamp, were inspired to create a social gaming experience that brings people together, moving away from the often isolating nature of virtual reality. The initial idea stemmed from a realization that VR headsets can create barriers to group interaction. The company launched its first venue in London in October 2019 and has since expanded significantly across the US, UK, Europe, and the UAE.\n\nThe core of the business is the \"Gamebox,\" an interactive smart room designed for groups of two to six players. These rooms utilize a combination of projection mapping, touch-sensitive walls, 3D motion tracking, and surround sound to create immersive, shared adventures without the need for headsets. Players wear lightweight visors with tracking dots, allowing the system to follow their movements as they interact with the game projected on the 360-degree screens. The experience is designed to be collaborative, requiring teamwork to solve puzzles and complete challenges in 30-to-60-minute sessions. The target market is broad, encompassing families, couples on date nights, groups of friends, and corporate teams seeking team-building activities.\n\nRevenue is generated through ticket sales for these gaming sessions, with prices around $30 per person for an hour. The company''s business model includes both company-owned venues and a franchise and concession model. This allows Immersive Gamebox to be integrated into existing entertainment centers, movie theaters, and malls. The firm has aggressively pursued global expansion, signing significant franchise deals to enter new markets. The company develops its game library in-house and through strategic IP partnerships with major entertainment studios like Netflix, Paramount, and Sony Pictures. This has led to the creation of popular games based on franchises such as \"Squid Game,\" \"Ghostbusters,\" \"PAW Patrol,\" and \"Angry Birds\".\n\nKeywords: social gaming, immersive entertainment, location-based entertainment, interactive gaming, franchise, projection mapping, motion tracking, group experiences, experiential retail, out-of-home entertainment","image":"storage.googleapis.com/dealroom-images-production/2025/10/13/244a00db7eba4861803ab1bdecd5aeb1.png","dealroom_url":"https://app.dealroom.co/companies/electronic_theatre","links":{"website":"https://electricplaybox.com/","linkedin":"https://www.linkedin.com/company/immersivegamebox/","twitter":"https://twitter.com/electrnctheatre","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/electronic-theatre"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.504356,"lon":-0.1034142},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.504356,"lon":-0.1034142}],"roles":[],"taxonomy":[{"id":12006,"name":"database","type":"techstack_category"},{"id":39406,"name":"sales","type":"techstack_category"},{"id":10001203,"name":"Media","type":"industry"},{"id":22206,"name":"hris management","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":48906,"name":"web fonts","type":"techstack_category"},{"id":35006,"name":"recruitment marketing","type":"techstack_category"},{"id":30806,"name":"online form builders","type":"techstack_category"},{"id":29106,"name":"marketing","type":"techstack_category"},{"id":29706,"name":"marketing automation","type":"techstack_category"},{"id":9406,"name":"customer relationship management","type":"techstack_category"},{"id":23106,"name":"human resources","type":"techstack_category"},{"id":113707,"name":"Angel","type":"ownership"},{"id":20806,"name":"frameworks and libraries","type":"techstack_category"},{"id":51106,"name":"content management system","type":"techstack_category"},{"id":28906,"name":"other advertising software","type":"techstack_category"},{"id":31606,"name":"online video platforms","type":"techstack_category"},{"id":29406,"name":"marketing analytics","type":"techstack_category"},{"id":30706,"name":"marketing performance measurement","type":"techstack_category"},{"id":25806,"name":"it infrastructure","type":"techstack_category"},{"id":2294801,"name":"uk is8 creative industries","type":"sector"},{"id":55106,"name":"web platform extensions","type":"techstack_category"},{"id":41806,"name":"tag management","type":"techstack_category"},{"id":50006,"name":"widgets","type":"techstack_category"},{"id":39906,"name":"search engines","type":"techstack_category"},{"id":8806,"name":"content delivery network","type":"techstack_category"},{"id":35106,"name":"programming languages","type":"techstack_category"},{"id":612,"name":"Breakout stage","type":"growth_stage"},{"id":5106,"name":"audio-video-graphics","type":"techstack_category"},{"id":16606,"name":"advertising","type":"techstack_category"},{"id":2042501,"name":"Pay Per Result","type":"sector"},{"id":30906,"name":"miscellaneous","type":"techstack_category"},{"id":34806,"name":"programming","type":"techstack_category"},{"id":311401,"name":"Ticketing","type":"sector"},{"id":24206,"name":"javascript libraries","type":"techstack_category"},{"id":53406,"name":"wordpress plugins","type":"techstack_category"},{"id":26706,"name":"intelligence and analytics","type":"techstack_category"},{"id":46206,"name":"video players","type":"techstack_category"},{"id":17006,"name":"analytics","type":"techstack_category"},{"id":317601,"name":"Leisure","type":"sector"},{"id":124403,"name":"Gaming","type":"industry"},{"id":48106,"name":"web analytics","type":"techstack_category"},{"id":51306,"name":"platform as a service","type":"techstack_category"},{"id":47006,"name":"visualisation software","type":"techstack_category"},{"id":211,"name":"b2c","type":"client_focus"},{"id":323901,"name":"Social","type":"sector"},{"id":73501,"name":"Digital Entertainment","type":"sector"},{"id":20506,"name":"font scripts","type":"techstack_category"},{"id":50906,"name":"social networks","type":"techstack_category"},{"id":1206,"name":"blogs","type":"techstack_category"},{"id":4206,"name":"applicant tracking systems","type":"techstack_category"},{"id":11006,"name":"design","type":"techstack_category"},{"id":43906,"name":"tools","type":"techstack_category"},{"id":4006,"name":"captcha","type":"techstack_category"},{"id":49406,"name":"web tools and plugins","type":"techstack_category"},{"id":49106,"name":"web hosting","type":"techstack_category"}],"launch_date":"2018-03","closing_date":null,"employees_count":129,"added_at":"2020-01-07T13:08:35.000Z","updated_at":"2026-11-05T01:05:15.706Z","subtype":"company","classifications":["startup","vc_backed","funded"],"employee_count_1y_growth":14.159292,"status":"operational","signal_rating":79.72,"unicorn_type":null,"became_unicorn_date":null,"became_thoroughbred_date":null,"exit_date":null,"investor":null,"funding":{"total":19833330,"total_vc":19833330,"rounds_count":3},"valuation":{"value":49999980,"year":2021,"month":6},"jobs":{"is_hiring":false,"open_count":0},"founders":{"total":1,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":"Co-founder","titles":["CEO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Will Dean","type":"person","uuid":"f5e8fb57-6efc-434d-bb3c-6cb42ce919c7","image":"storage.googleapis.com/dealroom-images-production/2026/10/29/fabfa16eb12b0f15589e2394deacbc72.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/will_dean","classifications":["serial_founder","super_founder"]}}]},"patents":null,"revenue":null,"traffic":{"monthly_visits":960,"growth_3m":1},"available":["founders","traffic"]}', '2026-11-05T15:41:34.047Z', 'Immersive Gamebox, formerly known as Electric Playbox, is a social entertainment and gaming company founded in 2018 by Will Dean and David Spindler. Dean, who previously founded the Tough Mudder endurance events, and Spindler, who co-founded Tough Mudder Bootcamp, were inspired to create a social gaming experience that brings people together, moving away from the often isolating nature of virtual reality. The initial idea stemmed from a realization that VR headsets can create barriers to group interaction. The company launched its first venue in London in October 2019 and has since expanded significantly across the US, UK, Europe, and the UAE.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('6c11220f-280f-4287-ae4e-782e4eb3b9bd', 'FarmDrop', 'farmdrop.co.uk', 'http://farmdrop.co.uk', 'https://www.linkedin.com/company/farmdrop-ltd/', 'https://app.dealroom.co/companies/farmdrop_1', 'Farmdrop - Mind-blowing groceries, delivered.', 'London', 'United Kingdom', 2012, 34, 6.25, 28674241, 7, 11822435, 2020, 'operational', '[{"uuid":"bb7b0b36-c4af-4a85-a6e7-702378367b98","name":"Ben Pugh"}]', '{"uuid":"6c11220f-280f-4287-ae4e-782e4eb3b9bd","type":"organization","domain":"farmdrop.co.uk","name":"FarmDrop","tagline":"Farmdrop - Mind-blowing groceries, delivered.","about":"Farmdrop was an online grocery delivery service founded in London in 2012 by Ben Pugh, with co-founders Winnie Pugh and Charles Benedict Pugh. The company''s mission was to create a more direct and equitable food supply chain by connecting consumers with local farmers and producers. Pugh, a former City broker for Morgan Stanley with a background that also included sailing and working on the Ocado stock flotation, was motivated by a passion for the environment and a dissatisfaction with the conventional supermarket system. He observed the unfair distribution of value, where producers received a small fraction of the final retail price, and aimed to build a system that provided a better deal for farmers. \n\nThe business operated as an online marketplace where customers could order a wide range of products, including fresh fruits, vegetables, meat, dairy, and ethically-sourced household goods, directly from a network of over 450 producers. Farmdrop''s model was designed to disintermediate the traditional supply chain, allowing farmers to receive a significantly larger share of the retail price—initially around 70-80%. Revenue was generated through a commission on each transaction, with the majority of the price going back to the producer. The service initially launched with a ''click and collect'' model at local hubs like pubs and community centres before transitioning to a direct-to-home delivery service using a fleet of electric vans. \n\nThe platform provided logistical support, aggregating customer orders and coordinating delivery routes, allowing producers to focus on their craft. A key feature was that much of the produce was harvested to order, which minimized food waste compared to traditional retail. Over its lifespan, Farmdrop raised a total of $55.4M (£36M+) through multiple funding rounds from investors including Atomico, LGT Impact Ventures, and Belltown Ventures. Despite its ethical mission and significant backing, the company faced challenges in scaling its complex logistics and achieving profitability. After expanding its product range and delivery network, the company ultimately entered administration in December 2021, ceasing trading after failing to secure the necessary additional funding to continue operations. \n\nKeywords: online grocery, farm-to-table, ethical grocer, food delivery, local produce, sustainable farming, direct-to-consumer, food supply chain, e-commerce, social enterprise","image":"storage.googleapis.com/dealroom-images-production/2025/09/26/a9aba3b077b97786fe68ff416c8e4d7d.png","dealroom_url":"https://app.dealroom.co/companies/farmdrop_1","links":{"website":"http://farmdrop.co.uk","linkedin":"https://www.linkedin.com/company/farmdrop-ltd/","twitter":"https://twitter.com/farmdrop","instagram":null,"angellist":"https://angel.co/farmdrop-2","crunchbase":"https://www.crunchbase.com/organization/farmdrop"},"locations":[{"r