ntinuous integration","type":"techstack_category"},{"id":10000803,"name":"Food","type":"industry"},{"id":8406,"name":"containerization","type":"techstack_category"},{"id":32506,"name":"operating systems","type":"techstack_category"},{"id":28106,"name":"maps","type":"techstack_category"},{"id":49406,"name":"web tools and plugins","type":"techstack_category"}],"launch_date":"2012-06","closing_date":null,"employees_count":34,"added_at":"2020-11-03T19:06:11.000Z","updated_at":"2026-11-05T01:02:41.181Z","subtype":"company","classifications":["startup","vc_backed","funded"],"employee_count_1y_growth":6.25,"status":"operational","signal_rating":79.14,"unicorn_type":null,"became_unicorn_date":null,"became_thoroughbred_date":null,"exit_date":null,"investor":null,"funding":{"total":28674241,"total_vc":28674241,"rounds_count":7},"valuation":{"value":36000000,"year":2020,"month":6},"jobs":{"is_hiring":false,"open_count":0},"founders":{"total":1,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":null,"titles":["CEO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2012","end_date":null,"person":{"name":"Ben Pugh","type":"person","uuid":"bb7b0b36-c4af-4a85-a6e7-702378367b98","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/59f41c1059f6d9f9dea559c8da6fad32.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/ben_pugh_2","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":11822435,"year":2020},"traffic":{"monthly_visits":770,"growth_3m":133},"available":["founders","revenue","traffic"]}', '2026-11-05T15:42:01.499Z', 'Farmdrop was an online grocery delivery service founded in London in 2012 by Ben Pugh, with co-founders Winnie Pugh and Charles Benedict Pugh. The company''s mission was to create a more direct and equitable food supply chain by connecting consumers with local farmers and producers. Pugh, a former City broker for Morgan Stanley with a background that also included sailing and working on the Ocado stock flotation, was motivated by a passion for the environment and a dissatisfaction with the conventional supermarket system. He observed the unfair distribution of value, where producers received a small fraction of the final retail price, and aimed to build a system that provided a better deal for farmers. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('662e33d9-f490-4034-86ea-e4c3b3c14164', 'Graphy', 'graphy.app', 'https://graphy.app', 'https://www.linkedin.com/company/graphyhq/', 'https://app.dealroom.co/companies/graphy', 'Create highly-visual and flexible dashboards with data from hundreds of apps', 'London', 'United Kingdom', 2018, 37, 8.823529, 7660604, 2, 2272726, 2023, 'operational', '[{"uuid":"e770f732-4801-49ac-89f2-ce02e2dca6d9","name":"Roman Sevast"},{"uuid":"a056b621-b483-44e1-8f34-6e605459c868","name":"Roman Sîrbu"},{"uuid":"97549fc6-ab2e-4a63-b212-b5faaee1f8c1","name":"Andrey Vinitsky"}]', '{"uuid":"662e33d9-f490-4034-86ea-e4c3b3c14164","type":"organization","domain":"graphy.app","name":"Graphy","tagline":"Create highly-visual and flexible dashboards with data from hundreds of apps","about":"Graphy operates as a data analytics and visualization firm, providing a platform designed to simplify how teams and individuals communicate data-driven narratives. The company was established in 2019 in London, United Kingdom, by CEO Andrey Vinitsky and Co-founder Roman Sirbu. Vinitsky, in a blog post, explained that the founding vision was to build a platform that radically improves the way people work with data after experiencing firsthand the productivity loss from grappling with data scattered across multiple services. The company secured $10.5 million in seed funding over two rounds in 2019 from investors including Northzone and Coatue. \n\nInitially, Graphy developed a comprehensive product covering the entire data value chain, from ingestion and modeling to analysis and visualization. However, this complex solution struggled to gain user engagement. This led to a strategic pivot towards a leaner product, \"Graphy Lite,\" which focused on solving one core problem: creating visually appealing charts quickly. This shift proved successful, resulting in significant user growth, reaching 50,000 users within ten months of enabling account creation. \n\nThe company''s core offering is a no-code, AI-powered platform that enables users to transform data into interactive charts and dashboards. The service is built for a professional clientele including marketing managers, data analysts, and founders who need to present data insights for business reports or investor updates. The platform features one-click data import from sources like Google Analytics, HubSpot, and spreadsheets, aiming to eliminate the need for complex technical integrations. Users can customize visualizations and embed the interactive charts into platforms such as Notion and Slack for broader communication. \n\nGraphy''s business model is freemium, allowing anyone to create a limited number of charts for free, which includes a Graphy watermark. Revenue is generated through an upgraded subscription plan that removes the branding, allows for custom brand colors, and unlocks additional features. The platform also offers an SDK and Embed APIs for businesses wanting to integrate the data storytelling capabilities directly into their own products. \n\nKeywords: data visualization, no-code analytics, interactive charts, data storytelling, business intelligence dashboards, Andrey Vinitsky, data reporting, freemium SaaS, data analysis tool, dashboard collaboration, chart maker, Notion integration, Slack integration, AI data insights, marketing analytics, financial data visualization, startup analytics, embeddable charts, Graphy.app, data communication","image":"storage.googleapis.com/dealroom-images-production/2026/03/22/84dd39bfafcc503f51095d97713c2d6a.png","dealroom_url":"https://app.dealroom.co/companies/graphy","links":{"website":"https://graphy.app","linkedin":"https://www.linkedin.com/company/graphyhq/","twitter":"https://twitter.com/graphyhq","instagram":"graphyhq","angellist":"https://angel.co/company/graphy","crunchbase":"https://www.crunchbase.com/organization/graphy"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.522614,"lon":-0.0856005},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.522614,"lon":-0.0856005}],"roles":[],"taxonomy":[{"id":12006,"name":"database","type":"techstack_category"},{"id":586801,"name":"Team Collaboration","type":"sector"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":35006,"name":"recruitment marketing","type":"techstack_category"},{"id":1006,"name":"ad exchanges","type":"techstack_category"},{"id":1202101,"name":"Productivity Tools","type":"sector"},{"id":309,"name":"Subscription","type":"income_stream"},{"id":83608,"name":"SaaS","type":"business_model"},{"id":113707,"name":"Angel","type":"ownership"},{"id":38806,"name":"performance","type":"techstack_category"},{"id":41606,"name":"system analytics & monitoring","type":"techstack_category"},{"id":49006,"name":"web frameworks","type":"techstack_category"},{"id":322901,"name":"SaaS","type":"sector"},{"id":12106,"name":"database management","type":"techstack_category"},{"id":111,"name":"b2b","type":"client_focus"},{"id":47606,"name":"web servers","type":"techstack_category"},{"id":1103001,"name":"App","type":"sector"},{"id":5106,"name":"audio-video-graphics","type":"techstack_category"},{"id":16606,"name":"advertising","type":"techstack_category"},{"id":30906,"name":"miscellaneous","type":"techstack_category"},{"id":7106,"name":"cloud infrastructure computing","type":"techstack_category"},{"id":295401,"name":"Analytics","type":"sector"},{"id":24206,"name":"javascript libraries","type":"techstack_category"},{"id":10014703,"name":"Enterprise Software","type":"industry"},{"id":17006,"name":"analytics","type":"techstack_category"},{"id":29206,"name":"other audio-video-graphics software","type":"techstack_category"},{"id":12906,"name":"devops","type":"techstack_category"},{"id":2054301,"name":"Interactive Dashboard","type":"sector"},{"id":40106,"name":"security","type":"techstack_category"},{"id":25406,"name":"issue trackers","type":"techstack_category"},{"id":48106,"name":"web analytics","type":"techstack_category"},{"id":4406,"name":"application development & management","type":"techstack_category"},{"id":212,"name":"Early stage","type":"growth_stage"},{"id":4206,"name":"applicant tracking systems","type":"techstack_category"},{"id":5806,"name":"charting","type":"techstack_category"},{"id":2053401,"name":"Remote Job","type":"sector"},{"id":7406,"name":"configuration management","type":"techstack_category"},{"id":285501,"name":"Collaboration","type":"sector"},{"id":4006,"name":"captcha","type":"techstack_category"},{"id":49406,"name":"web tools and plugins","type":"techstack_category"}],"launch_date":"2018-04","closing_date":null,"employees_count":37,"added_at":"2020-02-23T13:50:22.000Z","updated_at":"2026-11-05T01:04:51.533Z","subtype":"company","classifications":["startup","vc_backed","funded"],"employee_count_1y_growth":8.823529,"status":"operational","signal_rating":75.65,"unicorn_type":null,"became_unicorn_date":null,"became_thoroughbred_date":null,"exit_date":null,"investor":null,"funding":{"total":7660604,"total_vc":7660604,"rounds_count":2},"valuation":{"value":36363622,"year":2019,"month":12},"jobs":{"is_hiring":false,"open_count":0},"founders":{"total":3,"sort":"-is_strong_founder,-signal_rating","items":[{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Roman Sevast","type":"person","uuid":"e770f732-4801-49ac-89f2-ce02e2dca6d9","image":"storage.googleapis.com/dealroom-images-production/2025/04/22/18fb7e1e0acdb5b5117722212f7ac2bb.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/roman_sevast","classifications":["serial_founder","strong_founder"]}},{"raw_title":null,"titles":["Engineer","Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Roman Sîrbu","type":"person","uuid":"a056b621-b483-44e1-8f34-6e605459c868","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/4282800550db3636e4b46afa558a96eb.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/roman_s_rbu","classifications":["strong_founder"]}},{"raw_title":"Co-founder and Chief Executive Officer","titles":["CEO","Founder"],"is_founder":true,"is_executive":true,"is_partner":false,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Andrey Vinitsky","type":"person","uuid":"97549fc6-ab2e-4a63-b212-b5faaee1f8c1","image":"storage.googleapis.com/dealroom-images-production/2026/03/13/27da4654765d63fcb8b80462837dfe39.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/andrey_vinitsky","classifications":["strong_founder"]}}]},"patents":null,"revenue":{"value":2272726,"year":2023},"traffic":{"monthly_visits":110000,"growth_3m":-8},"available":["founders","revenue","traffic"]}', '2026-11-05T15:42:11.328Z', 'Graphy operates as a data analytics and visualization firm, providing a platform designed to simplify how teams and individuals communicate data-driven narratives. The company was established in 2019 in London, United Kingdom, by CEO Andrey Vinitsky and Co-founder Roman Sirbu. Vinitsky, in a blog post, explained that the founding vision was to build a platform that radically improves the way people work with data after experiencing firsthand the productivity loss from grappling with data scattered across multiple services. The company secured $10.5 million in seed funding over two rounds in 2019 from investors including Northzone and Coatue. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('c6e98581-9486-48a9-a7f9-76831a9b95a9', 'Housfy', 'housfy.com', 'https://housfy.com/', 'https://www.linkedin.com/company/housfy/', 'https://app.dealroom.co/companies/housfy', 'The digital alternative to any home service', 'Barcelona', 'Spain', 2016, 344, 14.666667, 43916649, 8, 37499985, 2025, 'operational', '[{"uuid":"cc285131-9d87-4e5b-8674-30a01fee24a2","name":"Miquel A. Mora"},{"uuid":"ee34d183-6f9a-4b52-a1c0-e74319fa36ed","name":"Albert Bosch"},{"uuid":"f4ecd41c-866d-48b7-9646-31ac5429292d","name":"Carlos Blanco"}]', '{"uuid":"c6e98581-9486-48a9-a7f9-76831a9b95a9","type":"organization","domain":"housfy.com","name":"Housfy","tagline":"The digital alternative to any home service","about":"Housfy is a digital platform that has transformed the traditional real estate model in Spain. The company provides a comprehensive ecosystem of home services, enabling individuals to buy and sell properties without the need for traditional real estate agencies, thus eliminating intermediaries and commissions. This model significantly reduces the costs associated with property transactions for consumers.\n\nBeyond property sales, Housfy has expanded its offerings to include mortgage brokerage, financial services, and other related home services. This strategic expansion has positioned the company as a one-stop-shop for all housing-related needs, from the initial transaction to the ongoing management and financing of a home. The platform''s business model is based on a fixed-fee structure for its services, providing transparency and predictability to its clients, who are primarily private individuals in the residential real estate market.\n\nKeywords: real estate, proptech, mortgage, brokerage, financial services, property, home services, commission-free, digital platform, real estate sales","image":"storage.googleapis.com/dealroom-images-production/2026/04/30/37b42bd18ee87d5fe84922160d96d134.png","dealroom_url":"https://app.dealroom.co/companies/housfy","links":{"website":"https://housfy.com/","linkedin":"https://www.linkedin.com/company/housfy/","twitter":"https://twitter.com/housfy_es","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/housfy-real-estate"},"locations":[{"role":"hq","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":41.400097,"lon":2.191494},{"role":"founding","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":41.400097,"lon":2.191494},{"role":"office","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":40.408382,"lon":-3.6889417}],"roles":["investor"],"taxonomy":[{"id":1313,"name":"corporate","type":"investor_type"},{"id":12006,"name":"database","type":"techstack_category"},{"id":127003,"name":"Real Estate","type":"industry"},{"id":35706,"name":"photo galleries","type":"techstack_category"},{"id":22906,"name":"human resource management system","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":12806,"name":"e-commerce platforms","type":"techstack_category"},{"id":48906,"name":"web fonts","type":"techstack_category"},{"id":35006,"name":"recruitment marketing","type":"techstack_category"},{"id":14106,"name":"editors","type