utive":false,"is_partner":false,"is_past":false,"start_date":"2016","end_date":null,"person":{"name":"Carlos Blanco","type":"person","uuid":"f4ecd41c-866d-48b7-9646-31ac5429292d","image":"storage.googleapis.com/dealroom-images-production/2026/05/05/73132ddd65503a62fbc3a06fdde02191.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/carlos_blanco","classifications":["serial_founder","super_founder"]}}]},"patents":null,"revenue":{"value":37499985,"year":2025},"traffic":{"monthly_visits":160000,"growth_3m":-6},"available":["founders","revenue","traffic","portfolio","exits"]}', '2026-11-05T15:41:56.622Z', 'Housfy is a digital platform that has transformed the traditional real estate model in Spain. The company provides a comprehensive ecosystem of home services, enabling individuals to buy and sell properties without the need for traditional real estate agencies, thus eliminating intermediaries and commissions. This model significantly reduces the costs associated with property transactions for consumers.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('5aaa6688-898c-47cb-91ae-4e391181d320', 'HungryPanda', 'hungrypanda.co', 'http://hungrypanda.co', 'https://www.linkedin.com/company/hungrypanda-ltd/', 'https://app.dealroom.co/companies/hungrypanda', 'HungryPanda is the global leader in delivering Chinese food and groceries with the extensive market coverage, highest user traffic as well as annual transaction volumes', 'London', 'United Kingdom', 2016, 684, 3.6363637, 208333250, 4, 159447124, 2025, 'operational', '[{"uuid":"c893aac2-cda6-4ee1-98bd-049bebae6555","name":"Eric DU"},{"uuid":"5cb2c8ad-584f-4792-b9a8-385c5bbcc377","name":"Eric LIU"}]', '{"uuid":"5aaa6688-898c-47cb-91ae-4e391181d320","type":"organization","domain":"hungrypanda.co","name":"HungryPanda","tagline":"HungryPanda is the global leader in delivering Chinese food and groceries with the extensive market coverage, highest user traffic as well as annual transaction volumes","about":"HungryPanda is a food and grocery delivery platform that specializes in serving Asian communities living abroad. Founded in 2017 by Kelu “Eric” Liu, the company was born from his personal experience as a computer science student at the University of Nottingham, UK. Liu identified a gap in the market, recognizing the difficulty overseas Chinese students and expatriates faced in finding authentic Asian cuisine and navigating English-only platforms. What started as a student project to solve this problem has expanded into a global operation. \n\nThe company''s core business revolves around a mobile application and website that connects users with a curated selection of local Asian restaurants and grocery stores. The platform is culturally attuned, offering support in languages like Mandarin and Cantonese, which helps bridge the language barrier for its target demographic. HungryPanda initially focused on Chinese communities but has since broadened its scope to include Japanese, Korean, and other Asian cuisines. In addition to restaurant meal delivery, the company launched \"PandaFresh\" for delivering fresh produce, groceries, and specialty Asian items, and \"VouchersPanda\" for lifestyle service discounts. \n\nHungryPanda''s business model is multifaceted. Its primary revenue stream comes from commission fees charged to partner restaurants and merchants for orders facilitated through the app. Additional revenue is generated from delivery fees paid by customers, which can vary based on distance and demand. The company also offers premium listings and advertising options for restaurants seeking better visibility on the platform and provides a subscription service for users, which includes benefits like free delivery. The company has demonstrated significant growth, operating in over 80 cities across 10 countries, including the UK, US, Australia, and nations in Europe and Asia. This expansion has been fueled by over $275 million in funding from various venture capital firms. The company reported achieving profitability in 2024 while maintaining an annual revenue growth rate of over 30%. \n\nKeywords: food delivery, grocery delivery, Asian cuisine, overseas Chinese market, e-commerce, restaurant delivery, online marketplace, mobile application, niche market, PandaFresh","image":"storage.googleapis.com/dealroom-images-production/2026/02/09/23f22170e9ff3f2d65a0d02359425adf.png","dealroom_url":"https://app.dealroom.co/companies/hungrypanda","links":{"website":"http://hungrypanda.co","linkedin":"https://www.linkedin.com/company/hungrypanda-ltd/","twitter":"https://x.com/hungrypanda_ltd","instagram":"hungrypanda_official","angellist":"https://angel.co/hungrypanda-1","crunchbase":"crunchbase.com/organization/hungrypanda"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.516445,"lon":-0.1200275},{"role":"founding","city":{"id":2871,"name":"Nottingham"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":52.95342,"lon":-1.149646}],"roles":["investor"],"taxonomy":[{"id":1313,"name":"corporate","type":"investor_type"},{"id":22906,"name":"human resource management system","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":48906,"name":"web fonts","type":"techstack_category"},{"id":35006,"name":"recruitment marketing","type":"techstack_category"},{"id":1155101,"name":"Platform","type":"sector"},{"id":6104,"name":"Food Logistics & Delivery","type":"sub_industry"},{"id":23106,"name":"human resources","type":"techstack_category"},{"id":45806,"name":"social sharing","type":"techstack_category"},{"id":113707,"name":"Angel","type":"ownership"},{"id":20806,"name":"frameworks and libraries","type":"techstack_category"},{"id":1960601,"name":"Food Delivery","type":"sector"},{"id":51106,"name":"content management system","type":"techstack_category"},{"id":28906,"name":"other advertising software","type":"techstack_category"},{"id":16506,"name":"enterprise","type":"techstack_category"},{"id":38806,"name":"performance","type":"techstack_category"},{"id":41606,"name":"system analytics & monitoring","type":"techstack_category"},{"id":25806,"name":"it infrastructure","type":"techstack_category"},{"id":2294801,"name":"uk is8 creative industries","type":"sector"},{"id":32206,"name":"message boards","type":"techstack_category"},{"id":41806,"name":"tag management","type":"