n. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('8a637f13-c57f-4e06-b8dd-90b14eda8f87', 'Innovamat', 'innovamat.es', 'http://innovamat.es/', 'https://www.linkedin.com/company/innovamat-education/', 'https://app.dealroom.co/companies/innovamat', 'Proposals for manipulative approaches to mathematics, created by experts and professors in didactics. Mathematics in Elementary School and Early Years. The K-12 Math Curriculum that teachers and students love! ', 'Barcelona', 'Spain', 2017, 384, 11.627907, 17274993, 4, 12116028, 2023, 'operational', '[{"uuid":"4107cf4a-eb23-4d79-b641-9e4ae8a5af29","name":"Isaac Sayol Piedra"},{"uuid":"4452d236-1512-4ed3-ad50-d0498c3f687b","name":"Andreu Dotti Boada"}]', '{"uuid":"8a637f13-c57f-4e06-b8dd-90b14eda8f87","type":"organization","domain":"innovamat.es","name":"Innovamat","tagline":"Proposals for manipulative approaches to mathematics, created by experts and professors in didactics. Mathematics in Elementary School and Early Years. The K-12 Math Curriculum that teachers and students love! ","about":"Innovamat is an educational technology company that has developed a platform aimed at transforming mathematics education for students from early childhood through secondary school. The firm was established in 2017 by a team with diverse and relevant backgrounds: Isaac Sayol, a mathematician and data scientist; Alex Coba, a computer scientist and entrepreneur; and Cecilia Bosch, a primary school teacher and mathematics specialist. This blend of expertise in mathematics, technology, and pedagogy forms the foundation of the company''s approach. The venture originated from the founders'' shared concern over traditional, memorization-based math teaching methods and a desire to make the subject more engaging and conceptually understandable for students. \n\nThe company operates in the K-12 education market, directly serving schools and teachers. Its business model is based on providing a comprehensive curricular proposal that includes a wide array of resources. These resources range from manipulable materials for hands-on learning to digital platforms featuring interactive activities and games, complemented by detailed teacher training and support. Revenue is generated through subscriptions or licensing fees paid by educational institutions for access to this integrated system. \n\nInnovamat''s core offering is a structured pedagogical program that guides students through mathematical concepts in a scaffolded manner, starting with concrete manipulation, moving to pictorial representation, and finally to abstract symbols. The platform provides personalized learning paths, allowing students to progress at their own pace while enabling teachers to monitor progress and identify areas where intervention is needed. A key differentiator is its focus on problem-solving and critical thinking rather than rote learning, aiming to build a solid and lasting understanding of mathematics. The company has achieved significant milestones, including rapid expansion into various regions of Spain and entry into international markets such as Italy and several Latin American countries, serving thousands of schools and hundreds of thousands of students. \n\nKeywords: edtech, mathematics education, K-12, pedagogical platform, curriculum development, teacher training, student assessment, personalized learning, educational resources, SaaS","image":"storage.googleapis.com/dealroom-images-production/2025/10/17/eed3f37161280c1cabe7472745bf908c.png","dealroom_url":"https://app.dealroom.co/companies/innovamat","links":{"website":"http://innovamat.es/","linkedin":"https://www.linkedin.com/company/innovamat-education/","twitter":"https://twitter.com/innovamat_cat","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/innovamat"},"locations":[{"role":"hq","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":41.38804,"lon":2.17001},{"role":"founding","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":41.38804,"lon":2.17001}],"roles":[],"taxonomy":[{"id":114407,"name":"accelerator","type":"ownership"},{"id":12006,"name":"database","type":"techstack_category"},{"id":35706,"name":"photo galleries","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":48906,"name":"web fonts","type":"techstack_category"},{"id":309,"name":"Subscription","type":"income_stream"},{"id":83608,"name":"SaaS","type":"business_model"},{"id":24006,"name":"javascript graphics","type":"techstack_category"},{"id":113707,"name":"Angel","type":"ownership"},{"id":10002203,"name":"Education","type":"industry"},{"id":20806,"name":"frameworks and libraries","type":"techstack_category"},{"id":51106,"name":"content management system","type":"techstack_category"},{"id":2178701,"name":"Steam","type":"sector"},{"id":31606,"name":"online video platforms","type":"techstack_category"},{"id":43306,"name":"software development","type":"techstack_category"},{"id":25806,"name":"it infrastructure","type":"techstack_category"},{"id":50106,"name":"wikis","type":"techstack_category"},{"id":111,"name":"b2b","type":"client_focus"},{"id":55106,"name":"web platform extensions","type":"techstack_category"},{"id":41806,"name":"tag management","type":"techstack_category"},{"id":50006,"name":"widgets","type":"techstack_category"},{"id":47606,"name":"web servers","type":"techstack_category"},{"id":39906,"name":"search engines","type":"techstack_category"},{"id":35106,"name":"programming languages","type":"techstack_category"},{"id":2178201,"name":"K-12","type":"sector"},{"id":209,"name":"Commission","type":"income_stream"},{"id":612,"name":"Breakout stage","type":"growth_stage"},{"id":5106,"name":"audio-video-graphics","type":"techstack_category"},{"id":18206,"name":"error and exception monitoring","type":"techstack_category"},{"id":48306,"name":"web and application servers","type":"techstack_category"},{"id":30906,"name":"miscellaneous","type":"techstack_category"},{"id":34806,"name":"programming","type":"techstack_category"},{"id":2806,"name":"caching","type":"techstack_category"},{"id":2606,"name":"business intelligence","type":"techstack_category"},{"id":12406,"name":"e-commerce","type":"techstack_category"},{"id":24206,"name":"javascript libraries","type":"techstack_category"},{"id":53406,"name":"wordpress plugins","type":"techstack_category"},{"id":26706,"name":"intelligence and analytics","type":"techstack_category"},{"id":46206,"name":"video players","type":"techstack_category"},{"id":17006,"name":"analytics","type":"techstack_category"},{"id":12906,"name":"devops","type":"techstack_category"},{"id":8304,"name":"Learning Tools and Resources","type":"sub_industry"},{"id":48106,"name":"web analytics","type":"techstack_category"},{"id":211,"name":"b2c","type":"client_focus"},{"id":4406,"name":"application development & management","type":"techstack_category"},{"id":20506,"name":"font scripts","type":"techstack_category"},{"id":1206,"name":"blogs","type":"techstack_category"},{"id":7206,"name":"continuous integration","type":"techstack_category"},{"id":49406,"name":"web tools and plugins","type":"techstack_category"}],"launch_date":"2017-01","closing_date":null,"employees_count":384,"added_at":"2020-01-20T11:53:42.000Z","updated_at":"2026-11-05T01:05:05.492Z","subtype":"company","clas