ated from the founders'' shared concern over traditional, memorization-based math teaching methods and a desire to make the subject more engaging and conceptually understandable for students. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('c939a947-2ab3-4281-bce5-e56e4e9dacd6', 'Insurama', 'insurama.com', 'https://insurama.com', 'https://www.linkedin.com/company/insurama/', 'https://app.dealroom.co/companies/insurama', 'Hub of digital products and services for the insurance industry', 'Madrid', 'Spain', 2018, 80, 6.6666665, 12916661, 3, 4202959, 2024, 'operational', '[{"uuid":"724eeadc-5001-44d3-8057-3a68d3ff5e5e","name":"Juancho C"},{"uuid":"951a7840-5daa-4880-82a1-4d92d68e5f41","name":"Sergio Balsa Pardo"}]', '{"uuid":"c939a947-2ab3-4281-bce5-e56e4e9dacd6","type":"organization","domain":"insurama.com","name":"Insurama","tagline":"Hub of digital products and services for the insurance industry","about":"Founded in 2018, Insurama operates as a Managing General Agent (MGA) in the insurtech sector, headquartered in Madrid, Spain. The company was established by Sergio Balsa Pardo. Insurama functions as a digital hub for insurance products and services, focusing on the online, end-to-end distribution and management of insurance solutions. \n\nThe firm''s core business is providing specialized insurance coverage for consumer electronic devices for both individual and business clients. Its product portfolio includes modular insurance for single mobile phones and multi-device plans, as well as coverage for items like scooters. A key feature of their offering is the inclusion of coverage for theft, such as pickpocketing, and extending protection to both new and used devices. The business model leverages an omnichannel distribution strategy, utilizing direct-to-consumer (B2C) sales through its own digital channels and call centers, and a business-to-business-to-consumer (B2B2C) approach through strategic partnerships with tech retailers and consumer finance companies. Strategic partners have included prominent names like Amazon, Xiaomi, and Banco Santander. Revenue is generated through the sale of these insurance policies.\n\nInsurama has built a proprietary, scalable platform that manages the entire insurance lifecycle, from quoting and sales to claims processing, ensuring a fully digital customer journey. The company has secured significant funding to fuel its growth, raising a total of $20.8 million over three rounds from investors including Inveready, All Iron Ventures, and BBVA Spark. This capital supports an aggressive international expansion plan which began in 2021. After establishing itself in Spain and Portugal, the company has expanded its operations into Latin America, with a presence in Mexico, Chile, Peru, and Colombia. \n\nKeywords: insurtech, MGA, device insurance, electronics protection, digital insurance, embedded insurance, omnichannel distribution, mobile insurance, multi-device coverage, claims processing, B2B2C insurance, consumer electronics, insurtech MGA, Sergio Balsa Pardo, international expansion, Latin America insurance, Helvetia, GNP Seguros, modular insurance, digital customer journey","image":"storage.googleapis.com/dealroom-images-production/2025/09/22/a90dff9ef1367830324e1d8327e0aacf.png","dealroom_url":"https://app.dealroom.co/companies/insurama","links":{"website":"https://insurama.com","linkedin":"https://www.linkedin.com/company/insurama/","twitter":null,"instagram":null,"angellist":null,"crunchbase":null},"locations":[{"role":"hq","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":40.460346,"lon":-3.6149223},{"role":"