der","Partner"],"is_founder":true,"is_executive":true,"is_partner":true,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Sergio Balsa Pardo","type":"person","uuid":"951a7840-5daa-4880-82a1-4d92d68e5f41","image":null,"subtype":null,"dealroom_url":"https://app.dealroom.co/people/sergio_balsa_pardo","classifications":["strong_founder"]}}]},"patents":null,"revenue":{"value":4202959,"year":2024},"traffic":{"monthly_visits":25000,"growth_3m":127},"available":["founders","revenue","traffic"]}', '2026-11-05T15:42:14.880Z', 'Founded in 2018, Insurama operates as a Managing General Agent (MGA) in the insurtech sector, headquartered in Madrid, Spain. The company was established by Sergio Balsa Pardo. Insurama functions as a digital hub for insurance products and services, focusing on the online, end-to-end distribution and management of insurance solutions. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('3f8a501a-2064-4ef4-b1c4-bfbd2daf4d12', 'MOO', 'moo.com', 'http://www.moo.com', 'https://www.linkedin.com/company/moo-com/', 'https://app.dealroom.co/companies/moo', 'MOO offers high-quality, affordable business cards and branded items like notebooks and water bottles', 'London', 'United Kingdom', 2006, 810, 7.001321, 3787877, 4, 90227237, 2024, 'operational', '[{"uuid":"4857b46a-68ac-41ca-9846-620abb0fadcb","name":"Richard Moross"}]', '{"uuid":"3f8a501a-2064-4ef4-b1c4-bfbd2daf4d12","type":"organization","domain":"moo.com","name":"MOO","tagline":"MOO offers high-quality, affordable business cards and branded items like notebooks and water bottles","about":"Moo is a leading online print and design company, founded in 2006 with a vision to revolutionize the print industry. Initially focused on providing high-quality, affordable business cards, Moo has since expanded its offerings to include a wide range of branded products, from notebooks and stickers to packaging and promotional items like water bottles.\n\nMoo''s commitment to excellence is evident in every aspect of its operations. The company designs, manufactures, and sells its products to customers worldwide, ensuring that each item meets the highest standards of quality and design. With a team of over 450 employees and five locations across the UK and US, Moo has grown significantly while maintaining its focus on delivering exceptional products.\n\nWhat sets Moo apart is its dedication to great design and superior quality. Unlike typical branded merchandise, Moo''s products are crafted with attention to detail and a keen eye for aesthetics. This ensures that customers receive items that not only serve their practical purposes but also enhance their brand image.\n\nMoo''s user-friendly platform allows customers to easily customize their products, choosing from a variety of templates and design options. Whether it''s creating unique business cards, personalized notebooks, or branded packaging, Moo provides the tools and resources needed to bring creative visions to life.\n\nThe company is also committed to sustainability and ethical practices. Moo sources materials responsibly and implements eco-friendly manufacturing processes, demonstrating its commitment to environmental stewardship.\n\nUnder the leadership of founder and CEO Richard Moross, Moo continues to innovate and explore new opportunities. The business has grown significantly over the years, and the team is always thinking about what comes next, ensuring that Moo remains at the forefront of the print and design industry.","image":"storage.googleapis.com/dealroom-images-production/2026/10/28/246ea11f4d36e2c2ef2e2f02c9db6d80.png","dealroom_url":"https://app.dealroom.co/companies/moo","links":{"website":"http://www.moo.com","linkedin":"https://www.linkedin.com/company/moo-com/","twitter":"https://twitter.com/overheardatmoo","instagram":"moo","angellist":"https://angel.co/moo-com-deleted","crunchbase":"http://www.crunchbase.com/organization/moo"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.51994,"lon":-0.1055476},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.51994,"lon":-0.1055476}],"roles":[],"taxonomy":[{"id":114407,"name":"acce