te":null,"person":{"name":"Richard Moross","type":"person","uuid":"4857b46a-68ac-41ca-9846-620abb0fadcb","image":"storage.googleapis.com/dealroom-images-production/2026/05/05/115ae6b1c3e52b4b9ac54249dc7128a8.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/richard_moross","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":90227237,"year":2024},"traffic":{"monthly_visits":1200000,"growth_3m":9},"available":["founders","revenue","traffic"]}', '2026-11-05T15:41:34.047Z', 'Moo is a leading online print and design company, founded in 2006 with a vision to revolutionize the print industry. Initially focused on providing high-quality, affordable business cards, Moo has since expanded its offerings to include a wide range of branded products, from notebooks and stickers to packaging and promotional items like water bottles.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('3efadf0d-659e-4e84-95a7-35447ef0d227', 'Matillion', 'matillion.com', 'http://matillion.com', 'https://www.linkedin.com/company/matillion-limited/', 'https://app.dealroom.co/companies/matillion_com', 'Makes data transformation software for cloud data warehouses', 'Salford', 'United Kingdom', 2011, 479, 2.7896996, 234378696, 7, 70434820, 2025, 'operational', '[{"uuid":"7dcc18b1-d412-40b9-99ce-f75adf86ee84","name":"Peter McCord"},{"uuid":"b3d54328-21ce-4dc7-9338-60e392796eb0","name":"Matthew Scullion"},{"uuid":"96a65265-eed5-4e04-a158-9ce75fe13653","name":"Ed Thompson"}]', '{"uuid":"3efadf0d-659e-4e84-95a7-35447ef0d227","type":"organization","domain":"matillion.com","name":"Matillion","tagline":"Makes data transformation software for cloud data warehouses","about":"Matillion is a data management platform that provides solutions for data teams to build, manage, and orchestrate data pipelines. The company operates in the data management and analytics market, serving a wide range of clients from various industries. Its primary focus is on enhancing productivity for data teams, both coders and non-coders, by offering tools to move, transform, and orchestrate data pipelines swiftly and efficiently.\n\nThe company''s business model is based on a usage-based pricing structure, charging clients only for the services they use. This approach allows for scalability as users and projects can be easily adjusted according to the client''s needs. Matillion''s platform is powered by artificial intelligence (AI), enabling the integration of large language models (LLMs) directly into data pipelines and the automatic generation of documentation to increase data literacy.\n\nMatillion''s platform also offers a library of hundreds of connectors, allowing data to be moved to and from any source or cloud data platform. This feature, coupled with the ability to perform complex transformations quickly and easily, meets the growing business demands for efficient data management. The platform also simplifies the orchestration of data pipelines, providing a unified view of all data pipelines, from no-code to SQL, Python, and dbt.\n\nIn summary, Matillion is a data management platform that leverages AI to enhance productivity for data teams, offering scalable solutions for building, managing, and orchestrating data pipelines.\n\nKeywords: Data Management, Data Pipelines, Artificial Intelligence, Large Language Models, Scalability, Usage-Based Pricing, Data Transformation, Data Orchestration, Cloud Data Platform, Productivity.","image":"storage.googleapis.com/dealroom-images-production/2025/09/26/846093e7ef72e553b9eb7cfc9ff4c86f.png","dealroom_url":"https://app.dealroom.co/companies/matillion_com","links":{"website":"http://matillion.com","linkedin":"https://www.linkedin.com/company/matillion-limited/","twitter":"https://twitter.com/matillion","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/matillion"},"locations":[{"role":"hq","city":{"id":5981,"name":"Salford"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":53.481323,"lon":-2.254771},{"role":"founding","city":{"id":1396581,"name":"Altrincham"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":53.383965,"lon":-2.3525462},{"role":"office","city":{"id":391,"name":"Denver"},"state":{"id":130892,"name":"Colorado"},