INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('23c4eb9c-523c-4158-9c90-29c817776ce1', 'Peanut', 'peanut-app.io', 'http://peanut-app.io', 'https://www.linkedin.com/company/peanut-app/', 'https://app.dealroom.co/companies/peanut', 'Social connection platform for women''s life stages', 'London', 'United Kingdom', 2016, 46, 6.976744, 12882571, 4, NULL, NULL, 'operational', '[{"uuid":"99ed7003-ebb2-469f-81cc-30aa186f5b51","name":"Michelle Kennedy"}]', '{"uuid":"23c4eb9c-523c-4158-9c90-29c817776ce1","type":"organization","domain":"peanut-app.io","name":"Peanut","tagline":"Social connection platform for women''s life stages","about":"Peanut App Ltd. operates an online social network exclusively for women, focusing on life stages such as fertility, pregnancy, motherhood, and menopause. The company was co-founded in London, UK, in 2017 by Michelle Kennedy, who serves as CEO, and Greg Orlowski. Kennedy, formerly the deputy CEO of the dating app Badoo and an inaugural board member of Bumble, drew from her professional background and personal experience of feeling isolated as a new mother to create the platform. \n\nThe app initially launched to help mothers connect with other local, like-minded women using a swipe-based mechanism. It has since expanded its scope to serve a broader female audience. In 2019, the company introduced a community for women trying to conceive. By 2021, it had added dedicated spaces for women navigating perimenopause and menopause. The platform allows users to join groups based on specific topics, interests, and life stages, such as due dates for expecting mothers. Key features include discussion forums, live audio conversations called \"Pods,\" identity verification for safety, and content filters to mute potentially triggering topics. \n\nPeanut has secured significant funding from investors, including a $12 million Series A round in May 2020 led by EQT Ventures, which brought its total funding to $21.8 million at the time. Other key investors include Index Ventures and the Female Founders Fund. The business model is focused on community growth, with potential future monetization through premium features. The app is free to join and available on iOS and Android devices. \n\nKeywords: social network, women''s health, motherhood, pregnancy, fertility, menopause, community app, female founders, femtech, peer support, social discovery, online community, parenting, women''s wellness, new mothers, trying to conceive, perimenopause, mom friends, female connection, venture capital","image":"storage.googleapis.com/dealroom-images-production/2026/10/28/b22545af395afad4e543e81dd980ff93.png","dealroom_url":"https://app.dealroom.co/companies/peanut","links":{"website":"http://peanut-app.io","linkedin":"https://www.linkedin.com/company/peanut-app/","twitter":"https://twitter.com/peanut_app","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/peanut-2"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.507446,"lon":-0.1277653},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.507446,"lon":-0.1277653}],"roles":[],"taxonomy":[{"id":3204,"name":"Health Platform","type":"sub_industry"},{"id":1313,"name":"corporate","type":"investor_type"},{"id":114407,"name":"ac