le":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Paula Quazi","type":"person","uuid":"c76fb96f-4dfc-4a64-8bd9-616395752899","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/67bbd8f288d131710984c87374a587c4.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/paula_quazi","classifications":["super_founder"]}},{"raw_title":null,"titles":["Founder"],"is_founder":true,"is_executive":false,"is_partner":false,"is_past":false,"start_date":"2018","end_date":null,"person":{"name":"Nick Green","type":"person","uuid":"f89d50f8-26ae-4183-96ea-0e4010a5a5c0","image":"storage.googleapis.com/dealroom-images-production/2025/04/22/a4abaca416e2f69bfc74550d54da5242.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/nick_green_2","classifications":["super_founder"]}}]},"patents":null,"revenue":{"value":44700000,"year":2025},"traffic":{"monthly_visits":110000,"growth_3m":0},"available":["founders","revenue","traffic"]}', '2026-11-05T15:41:48.292Z', 'Smol products, established in 2018 by co-founders Paula Quazi and Nick Green, operates as a direct-to-consumer challenger in the home care market. The company''s inception was driven by the founders'' shared experience within the consumer goods industry, notably at Unilever, where they identified a gap for affordably priced, eco-conscious cleaning solutions. Quazi''s background in life sciences and extensive experience in product development, combined with Green''s commercial expertise, provided the foundation for a business model that bypasses traditional retail channels. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('b8bdd4d5-dad0-4987-aadc-955be185064c', 'Sofar Sounds', 'sofarsounds.com', 'http://www.sofarsounds.com', 'https://www.linkedin.com/company/sofarsounds/', 'https://app.dealroom.co/companies/sofar_sounds', 'Global music community, hosting secret events', 'London', 'United Kingdom', 2009, 745, 6.2767477, 34765138, 5, 9615845, 2024, 'operational', '[{"uuid":"dfb4dd4b-965a-4bb7-b840-15594187909f","name":"Rafe Offer"},{"uuid":"ef43488b-f852-4dca-89b5-b2900656ee6a","name":"Rastiningdyah T. Sryantoro"}]', '{"uuid":"b8bdd4d5-dad0-4987-aadc-955be185064c","type":"organization","domain":"sofarsounds.com","name":"Sofar Sounds","tagline":"Global music community, hosting secret events","about":"Sofar Sounds operates as a global music community that bridges the gap between artists and audiences through distinctive live music events and artist services. Originating from a living room in London, the company has expanded organically to host events in 78 countries. Sofar Sounds is renowned for its non-traditional approach to live music, organizing secret concerts in unconventional venues such as living rooms, galleries, breweries, and rooftops. These unique settings provide a platform for artist discovery and foster a sense of community and connection among attendees. The company also offers artist services aimed at helping performers manage their fan relationships and build sustainable careers. Sofar Sounds generates revenue through ticket sales for its live events and by providing various services to artists. The company serves a diverse clientele, including music enthusiasts seeking unique concert experiences and artists looking to grow their fan base and sustain their creative endeavors.\n\nKeywords: live music, artist services, global community, unique venues, secret concerts, audience connection, artist discovery, sustainable careers, ticket sales, fan relationships.","image":"storage.googleapis.com/dealroom-images-production/2025/10/17/f26b33afd62a3da2ed9b8cdc9bfc7135.png","dealroom_url":"https://app.dealroom.co/companies/sofar_sounds","links":{"website":"http://www.sofarsounds.com","linkedin":"https://www.linkedin.com/company/sofarsounds/","twitter":"https://twitter.com/sofarsounds","instagram":null,"angellist":"https://angel.co/sofar-sounds","crunchbase":"https://www.crunchbase.com/organization/sofar-sounds"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.52435,"lon":-0.0732477},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.52435,"lon":-0.0732477}],"roles":["investor"],"taxonomy":[{"id":1313,"name":"corporate","type":"investor_type"},{"id":10006,"name":"data management","type":"techstack_category"},{"id":45606,"name":"social media marketing software","type":"techstack_category"},{"id":51406,"name":"software as a service","type":"techstack_category"},{"id":39406,"name":"sales","type":"techstack_category"},{"id":7506,"name":"corporate learning management systems","type":"techstack_category"},{"id":606,"name":"accounting","type":"techstack_category"},{"id":6006,"name":"chat","type":"techstack_category"},{"id":22906,"name":"human resource management system","type":"techstack_category"},{"id":22206,"name":"hris management","type":"techstack_category"},{"id":1