INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('f9726791-d6ec-4108-bd5a-f2034b6c473d', 'The Cambridge Satchel Company', 'cambridgesatchel.com', 'http://www.cambridgesatchel.com/', 'https://www.linkedin.com/company/cambridge-satchel/', 'https://app.dealroom.co/companies/the_cambridge_satchel_company', 'Hand-made leather satchels and accessories', 'London', 'United Kingdom', 2008, 46, 9.523809, 15909085, 2, 6338533, 2020, 'operational', '[{"uuid":"e65bdce3-af22-488d-a571-e277f45570de","name":"Julie Deane"}]', '{"uuid":"f9726791-d6ec-4108-bd5a-f2034b6c473d","type":"organization","domain":"cambridgesatchel.com","name":"The Cambridge Satchel Company","tagline":"Hand-made leather satchels and accessories","about":"The Cambridge Satchel Company, founded in 2008 by Julie Deane and her mother Freda Thomas, emerged from a personal mission to fund school fees, starting with a modest £600 budget at a kitchen table. This bootstrapped origin story is central to the brand''s identity, which champions traditional British craftsmanship. The company''s growth trajectory was significantly impacted by early adoption from fashion bloggers and a feature in a 2012 Google Chrome advertisement, which catapulted the brand to international recognition and boosted sales dramatically. A key milestone was the opening of its first physical store in Covent Garden in 2013, marking a significant step from a purely online retailer to a high-street presence. \n\nThe business operates in the affordable luxury leather goods market, specializing in handcrafted satchels and bags that draw inspiration from classic, vintage designs reimagined for a modern audience. The product line, which began with the traditional satchel, has expanded to include a variety of bags, backpacks, and small leather accessories for men, women, and children. A core feature of their offering is product personalization, allowing customers to emboss their items, which enhances the brand''s appeal as a gift and a personal statement piece. The company''s business model is direct-to-consumer, primarily through its e-commerce website, which serves a global customer base. This is complemented by its physical retail stores in key UK locations, including Cambridge, London, and Edinburgh. The brand''s commitment to British manufacturing is a key differentiator, with its own dedicated factory in the UK ensuring control over quality and reinforcing its brand ethos. \n\nKeywords: British manufacturing, leather goods, satchels, direct-to-consumer, e-commerce, affordable luxury, personalization, fashion accessories, bootstrapped, craftsmanship","image":"storage.googleapis.com/dealroom-images-production/2025/10/05/b1eabcc5d69b2c8f4fef045772326cbd.png","dealroom_url":"https://app.dealroom.co/companies/the_cambridge_satchel_company","links":{"website":"http://www.cambridgesatchel.com/","linkedin":"https://www.linkedin.com/company/cambridge-satchel/","twitter":"https://twitter.com/camsatchelco","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/the-cambridge-satchel-company"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.514267,"lon":-0.1257696},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.514267,"lon":-0.1257696}],"roles":[],"taxonom