INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('1b8796d7-e598-4e94-9c55-e27535f7cc7e', 'TreasurySpring', 'treasuryspring.com', 'treasuryspring.com', 'https://www.linkedin.com/company/treasuryspring/', 'https://app.dealroom.co/companies/spring_treasury', 'Regulated cash investment platform for fixed-term funds.', 'London', 'United Kingdom', 2016, 96, 5.4945054, 26125755, 6, 12002268, 2025, 'operational', '[{"uuid":"dd9fbe64-c370-46c0-89ae-5b83d7b1b1a2","name":"Matthew Longhurst"},{"uuid":"7ebe8868-0024-4843-8257-f2110f35d2c5","name":"James Skillen"},{"uuid":"3feb029b-3cdd-48e8-aba0-701f888485a9","name":"Kevin Cook"}]', '{"uuid":"1b8796d7-e598-4e94-9c55-e27535f7cc7e","type":"organization","domain":"treasuryspring.com","name":"TreasurySpring","tagline":"Regulated cash investment platform for fixed-term funds.","about":"TreasurySpring operates a financial technology platform that provides access to the wholesale money markets for institutional clients. Founded in London in 2016 by Kevin Cook, Matthew Longhurst, and James Skillen, the company was established to modernize cash investment infrastructure. The founders'' collective experience in hedge funds, fixed income, and asset management, particularly during the 2008 financial crisis, highlighted the need for more robust and accessible solutions for corporate cash management. The firm''s core offering is its regulated digital platform, which allows companies to invest excess cash into a variety of short-term, fixed-income products. Clients include a wide range of organizations, from FTSE 100 corporations and multinationals to startups, charities, and fund managers. For these entities, the platform offers a way to diversify holdings, manage risk, and increase returns on cash balances that might otherwise be held in low-yield bank accounts. The platform also serves institutional borrowers, such as governments, banks, and investment-grade corporations, by providing them with a flexible, low-cost source of funding from a diverse network of non-bank investors. The business model appears to be based on transactional fees linked to the volume and value of investments facilitated through the platform. TreasurySpring''s main product is the Fixed-Term Fund (FTF), a financial instrument it designed and first issued in 2018. FTFs function similarly to term deposits but provide direct, single-name exposure to high-quality issuers like governments or investment-grade banks and corporations for a set period, typically from one week to one year. The platform offers over 600 such products in multiple currencies, including secured options backed by collateral and unsecured options. This structure provides transparency and avoids the maturity transformation and co-mingling of assets common in traditional money market funds, thereby reducing certain risks for the investor. The company has raised approximately $43.5 million in funding, including a $29 million Series B round in June 2023 to fuel product development and international expansion. Keywords: cash investment platform, Fixed-Term Funds, FTFs, money markets, corporate treasury, cash management, institutional finance, short-term funding, fixed income, fintech, asset management, investment grade assets, government securities, secured bank assets, risk diversification, wholesale funding, digital investment, financial technology, corporate finance, liquidity management","image":"storage.googleapis.com/dealroom-images-production/2026/08/25/30434de4623374e93ca5c69f2b44984c.png","dealroom_url"