INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('5eac1b5a-0a94-44f7-a16b-e1d785016687', 'Typeform', 'typeform.com', 'http://www.typeform.com/', 'https://www.linkedin.com/company/typeform-/', 'https://app.dealroom.co/companies/typeform', 'Engaging conversational forms, surveys, and quizzes for businesses.', 'Barcelona', 'Spain', 2012, 920, 9.263658, 141651458, 6, 69166639, 2024, 'operational', '[{"uuid":"b541a37d-4534-4155-b098-567371f007a7","name":"David Okuniev"},{"uuid":"4553b209-5966-482d-90b5-94768f389855","name":"Robert Muñoz"}]', '{"uuid":"5eac1b5a-0a94-44f7-a16b-e1d785016687","type":"organization","domain":"typeform.com","name":"Typeform","tagline":"Engaging conversational forms, surveys, and quizzes for businesses.","about":"Typeform is a dynamic startup that specializes in creating user-friendly online forms and surveys. The company operates in the software-as-a-service (SaaS) market, providing tools that help businesses and organizations collect and analyze data efficiently. Typeform''s products include form builders, survey makers, quiz creators, and interactive video conversations through their VideoAsk tool. These products are designed to be engaging and easy to use, which helps clients get better response rates and more meaningful data.\n\nTypeform serves a diverse range of clients across various industries, including automotive, computer software, consumer goods, education, entertainment, financial services, food and beverage, government administration, healthcare, IT, marketing, nonprofits, professional services, public relations, real estate, sports, transportation, and travel hospitality. The company also caters to different roles within these organizations, such as marketing, human resources, product management, customer success, and education.\n\nThe business model of Typeform is subscription-based. Clients pay a recurring fee to access and use Typeform''s suite of tools. This model ensures a steady stream of revenue and allows the company to continuously improve and expand its offerings. Additionally, Typeform partners with various agencies to help clients integrate their tools into existing workflows, ensuring they get the most out of the platform.\n\nTypeform makes money primarily through these subscription fees. They offer different pricing tiers based on the features and level of service required by the client. This allows businesses of all sizes, from small startups to large enterprises, to find a plan that fits their needs and budget.\n\nIn summary, Typeform is a SaaS company that provides engaging and easy-to-use online forms and surveys. It serves a wide range of industries and roles, operates on a subscription-based model, and partners with agencies to maximize client success.\n\nKeywords: SaaS, online forms, surveys, data collection, user-friendly, subscription-based, diverse industries, client-focused, workflow integration, partner agencies.","image":"storage.googleapis.com/dealroom-images-production/2026/10/26/8f97bbdce588099e5261bdd06e61afc5.png","dealroom_url":"https://app.dealroom.co/companies/typeform","links":{"website":"http://www.typeform.com/","linkedin":"https://www.linkedin.com/company/typeform-/","twitter":"https://twitter.com/typeform","instagram":null,"angellist":"https://angel.co/typeform-1","crunchbase":"https://www.crunchbase.com/organization/typeform"},"locations":[{"role":"hq","city":{"id":291,"name":"Barcelona"},"state":{"id":433072,"name":"Catalonia"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Eur