INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('6a165323-7d03-4463-a1ac-3052fca51dce', 'Urbanitae', 'urbanitae.com', 'http://urbanitae.com/', 'https://www.linkedin.com/company/urbanitae/', 'https://app.dealroom.co/companies/urbanitae', 'The meeting point between the small investor and the best real estate developers', 'Madrid', 'Spain', 2017, 124, 24, 9999996, 4, 8450194, 2024, 'operational', '[{"uuid":"58c2bac7-f7e5-4ae6-96fa-1dca5168ac6e","name":"Diego Bestard"},{"uuid":"dabf0503-efae-4cef-a1e4-41f0dd12d9b4","name":"Eduardo Navarro"}]', '{"uuid":"6a165323-7d03-4463-a1ac-3052fca51dce","type":"organization","domain":"urbanitae.com","name":"Urbanitae","tagline":"The meeting point between the small investor and the best real estate developers","about":"Urbanitae is a real estate crowdfunding platform that allows small investors to participate in large-scale real estate projects, a market traditionally dominated by institutional investors. The company operates primarily in the Spanish market, where it holds a significant market share, and has recently expanded its operations to Portugal. Its business model is based on a B2C approach, connecting individual investors with real estate developers seeking funding for their projects. Urbanitae''s revenue is likely generated through fees charged to both investors and developers for successful funding campaigns.\n\nThe platform offers a variety of investment opportunities, including rental projects and luxury real estate developments. By pooling funds from multiple investors, Urbanitae enables access to diversified real estate portfolios with potentially high returns. The company emphasizes security and transparency, providing detailed information and analysis for each project to help investors make informed decisions.\n\nKeywords: real estate crowdfunding, property investment, financial services, peer-to-peer lending, alternative finance, real estate development, investment platform, fintech, property technology, crowdinvesting","image":"storage.googleapis.com/dealroom-images-production/2025/10/06/ddcc11d69b1e3d2221dcc1c064c8f321.png","dealroom_url":"https://app.dealroom.co/companies/urbanitae","links":{"website":"http://urbanitae.com/","linkedin":"https://www.linkedin.com/company/urbanitae/","twitter":"https://twitter.com/urbanitae","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/urbanitae"},"locations":[{"role":"hq","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":40.42449,"lon":-3.6818552},{"role":"founding","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":40.42449,"lon":-3.6818552},{"role":"office","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":40.426403,"lon":-3.6883228}],"roles":[],"taxonomy":[{"id":127003,"name":"Real Estate","type":"industry"},{"id":21406,"name":"help desk software","type":"techstack_category"},{"id":114007,"name":"Venture Capital","type":"ownership"},{"id":30806,"name":"online form builders","type":"techstack_category"},{"id":14106,"name":"editors","type":"techstack_category"},{"id":29706,"name":"marketing automation","type":"techstack_category"},{"id":34106,"name":"page builders","type":"techstack_category"},{"id":113707