":"2008","end_date":null,"person":{"name":"Ignasi Vilajosana","type":"person","uuid":"ec4a0997-f8bf-49b3-b0ea-6c7df26c6228","image":"storage.googleapis.com/dealroom-images-production/2025/04/22/adb004e7c0e458233ab81fd162230836.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/ignasi_vilajosana","classifications":["serial_founder","strong_founder"]}}]},"patents":null,"revenue":{"value":12651510,"year":2023},"traffic":{"monthly_visits":15000,"growth_3m":15},"available":["founders","revenue","traffic"]}', '2026-11-05T15:41:45.159Z', 'Worldsensing is a technology company specializing in IoT (Internet of Things) wireless monitoring solutions for critical infrastructures. The company focuses on enhancing safety and efficiency in industries such as construction, mining, rail, and civil infrastructure. By providing data loggers and sensors, Worldsensing enables continuous monitoring of structural integrity for large-scale projects like bridges, tunnels, and tailings dams. This helps prevent incidents and ensures safer operations.
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('61ca2e33-0b20-46f9-92d4-995098ab1380', 'fintonic', 'fintonic.com', 'http://fintonic.com', 'https://www.linkedin.com/company/fintonic/', 'https://app.dealroom.co/companies/fintonic', 'Personal finance app for loans, insurance, and savings', 'Madrid', 'Spain', 2011, 110, 7.8431373, 50166647, 8, 1245581, 2023, 'operational', '[{"uuid":"8bf5eda0-236f-4571-a6c0-a56344ffa9db","name":"Lupina Iturriaga"},{"uuid":"b7098b57-7005-490b-a242-5abe2b3851f4","name":"Marcos Icardo"},{"uuid":"bca647ed-4285-4389-aa1e-69c91eb8d528","name":"Sergio Chalbaud"}]', '{"uuid":"61ca2e33-0b20-46f9-92d4-995098ab1380","type":"organization","domain":"fintonic.com","name":"fintonic","tagline":"Personal finance app for loans, insurance, and savings","about":"Fintonic is a Spanish fintech company founded in 2012 by Lupina Iturriaga, Sergio Chalbaud, and Marcos Icardo. The founders utilized their backgrounds in finance and banking to develop a personal finance application. The platform operates as a financial aggregator, allowing users to connect their various bank accounts and cards to gain a consolidated view of their finances. \n\nThe company''s primary service is a mobile application that provides tools for personal financial management. It automatically categorizes user expenses, tracks accounts, and offers monthly forecasts to help users manage their money. A key feature is the \"FinScore,\" a proprietary credit scoring system that assesses a user''s financial health to facilitate access to better financing conditions. Fintonic''s business model is centered on its marketplace, where it earns commissions by connecting users with financial products from over 50 partner entities. The company provides access to personal loans, insurance, investment products like indexed funds, and interest-bearing accounts. The service is free for users, as revenue is generated from the financial institutions and service providers on its platform. \n\nHeadquartered in Madrid, Spain, Fintonic has expanded its operations to include Mexico and Chile. Over its history, the company has raised a total of $54.8 million over several funding rounds, with its latest Series D round in June 2023. Major investors include ING Ventures, PSN Group, Atresmedia, and Onza Capital. The company is licensed by the Bank of Spain to provide account information and payment initiation services, complying with the European PSD2 directive. \n\nKeywords: personal finance, fintech, financial management, loan marketplace, account aggregation, credit score, FinScore, insurance brokerage, expense tracking, savings tools, investment platform, PSD2, online lending, consumer finance, mobile banking, financial wellness, Lupina Iturriaga, Sergio Chalbaud, Marcos Icardo, Madrid fintech","image":"storage.googleapis.com/dealroom-images-production/2026/10/26/ee379ab71b8502f2fb4554259d6ade52.png","dealroom_url":"https://app.dealroom.co/companies/fintonic","links":{"website":"http://fintonic.com","linkedin":"https://www.linkedin.com/company/fintonic/","twitter":"https://twitter.com/fintonic","instagram":null,"angellist":null,"crunchbase":"http://www.crunchbase.com/company/fintonic"},"locations":[{"role":"hq","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":283,"name":"Spain"},"continent":{"id":34,"name":"Europe"},"lat":40.43597,"lon":-3.6892164},{"role":"founding","city":{"id":351,"name":"Madrid"},"state":{"id":444302,"name":"Community of Madrid"},"country":{"id":2