false,"start_date":"2011","end_date":null,"person":{"name":"Sergio Chalbaud","type":"person","uuid":"bca647ed-4285-4389-aa1e-69c91eb8d528","image":"storage.googleapis.com/dealroom-images-production/2025/04/18/cbc0169f7f239051ca38979e1208304d.png","subtype":null,"dealroom_url":"https://app.dealroom.co/people/sergio_chalbaud","classifications":["serial_founder","super_founder"]}}]},"patents":null,"revenue":{"value":1245581,"year":2023},"traffic":{"monthly_visits":190000,"growth_3m":-21},"available":["founders","revenue","traffic","portfolio","exits"]}', '2026-11-05T15:42:14.880Z', 'Fintonic is a Spanish fintech company founded in 2012 by Lupina Iturriaga, Sergio Chalbaud, and Marcos Icardo. The founders utilized their backgrounds in finance and banking to develop a personal finance application. The platform operates as a financial aggregator, allowing users to connect their various bank accounts and cards to gain a consolidated view of their finances. 
INSERT INTO companies (uuid, name, domain, website, linkedin, dealroom_url, tagline, hq_city, hq_country, launch_year, employees, employee_growth_1y, funding_total, funding_rounds, revenue, revenue_year, status, founders_json, raw_json, fetched_at, about, industries_json, classifications_json, signal_rating, monthly_visits, is_hiring, open_jobs, valuation, ebitda, ebitda_year, profit, profit_year, financials_json, financials_fetched_at, currency, last_round_date, last_round_label, last_round_amount) VALUES ('1c3e1562-4b56-4651-b553-1c10ca9ba020', 'floLIVE', 'flolive.net', 'https://flolive.net/', 'https://www.linkedin.com/company/flo-live/', 'https://app.dealroom.co/companies/flo_live', 'Operates a self-developed, cloud-based connectivity enablement platform designed and built especially for IoT', 'London', 'United Kingdom', 2015, 178, 3.488372, 66818155, 4, 11632622, 2024, 'operational', '[{"uuid":"6e67fb58-d62c-4c19-8086-d0a0ca9a2962","name":"Arik Aberjel"},{"uuid":"1cb0971f-ee23-4a3b-981a-e52d1af198ea","name":"Jeegar Swaly"}]', '{"uuid":"1c3e1562-4b56-4651-b553-1c10ca9ba020","type":"organization","domain":"flolive.net","name":"floLIVE","tagline":"Operates a self-developed, cloud-based connectivity enablement platform designed and built especially for IoT","about":"The world is experiencing a significant transformation. The Internet of Things (IoT) industry is revolutionizing life as we know it, enabling manufacturers to monitor and exchange production status in real time. Serving as a powerful tool to address global connectivity and challenges like climate change and improving health care, IoT is shaping the future. \n\nfloLIVE is a global technology company that provides innovative connectivity solutions to the  IoT industry. The company offers the largest hyperlocal data network, providing centrally managed local connectivity for any device anywhere. \n\nServices supply users with direct network access, connectivity control, device monitoring, access to real-time events, the possibility to switch operators remotely, and seamless device performance.\n\nAs enterprises continue to move towards IoT-facilitated digital transformation, connectivity needs are evolving. floLIVE provides seamless global cellular connectivity with its cloud-based platform that manages connectivity, billing, and core network operations fully designed for IoT that optimizes performance. \n \nThis platform brings the power of cloud computing to enterprise data centers, offering a secure, low-latency, and high-speed network experience. Furthermore, floLIVE offers a Global IoT Network as-a-service (LTE/5G), designed specifically for narrowband, battery-operated device-to-cloud use cases adding higher quality, better availability and tighter security than ever before, without the operational headaches or lengthy timelines.\n\nThe company operates in the IoT market, serving a diverse range of clients that include:\n\n•\tGlobal enterprises- floLIVE provides a fully automated service for global enterprises with a unique, patented SIM bootstrap technology that enables devices to be activated anywhere in the world and receive connectivity services through a local carrier, to overcome permanent roaming restrictions. Through a unified panel we provide control, flexibility and security needed for building tomorrow’s global enterprise IoT solutions.\n•\tMobile Operators- floLIVE provides the only solution for telecom that expands IoT services globally, reducing operational complexities and reducing TCO. The IoT management suite comprises four main building blocks: Automated Connectivity Management, IoT-oriented LTE/5G Core Network, eSIM Management, and Business Support Systems (BSS), including rating, online charging, advanced billing and invoicing.\n•\tIoT service providers- floLIVE provides improved global management and control capabilities with a single global IoT connectivity provider, eliminating multi-operator complexities. With floLIVE’s IoT solutions, service providers can avoid architectural and roaming limitations and focus on delivering and monetizing value-added services. floLIVE’s platform allows IoT service providers to customize and add products and services to their offering independently, avoiding vendor lock-in, lengthy change requests and lowering costs. \n\nfloLIVE''s revenue is generated through a pay-as-you-grow model, where clients only pay for active IoT devices, allowing costs to scale with success. This model, combined with the company''s advanced microservices architecture, provides clients with the flexibility to pick and choose components and integrate with existing infrastructure, facilitating the rapid and easy growth of global IoT solutions.","image":"storage.googleapis.com/dealroom-images-production/2025/10/13/f2111abe2d55e585b201cb75ae430fa0.png","dealroom_url":"https://app.dealroom.co/companies/flo_live","links":{"website":"https://flolive.net/","linkedin":"https://www.linkedin.com/company/flo-live/","twitter":"https://twitter.com/flolive7","instagram":null,"angellist":null,"crunchbase":"https://www.crunchbase.com/organization/flo-live"},"locations":[{"role":"hq","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.51194,"lon":-0.1366412},{"role":"founding","city":{"id":628061,"name":"London"},"state":{"id":130902,"name":"England"},"country":{"id":93,"name":"United Kingdom"},"continent":{"id":34,"name":"Europe"},"lat":51.51194,"lon":-0.1366412},{"role":"office","city":{"id":3171,"name":"Holon"},"state":{"id":326112,"name":"Tel Aviv District"},"country":{"id":423,"name":"Israel"},"continent":{"id":14,"name":"Asia"},"lat":32.014545,"lon":34.78555}],"roles":[],"taxonomy":[{"id":10006,"name":"data management","type":"techstack_category"},{"id":12006,"name":"database","type":"techstack_category"},{"id":35706,"name":"photo galleries","type":"techstack_category"},{"id":114007,"name":"